-- Priya's week 1 (days 1-7), hero 'priya': episodes, turns, phrases and her calendar.
-- The same week as Jun's (14-week1.sql, 15-weekend.sql), seen from the product manager's side: she runs the meetings.
-- Try: node tools/seed-json.mjs db/seed/52-priya.sql --out /tmp/claude-1000/priya-try/db.js, then node tools/db-lint.mjs on it.
-- Push: node tools/dolt.mjs push db/seed/52-priya.sql

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_d1_coffee', 'The usual at Nina''s cart', '니나의 카트에서 늘 마시던 걸로', 'coffee_cart', 'nina', 1, 5, '07:00', '10:30', NULL,
   'You stop at the coffee cart every morning. Order your usual latte with an extra shot and chat with Nina about the big week ahead.', '매일 아침 들르는 커피 카트입니다. 늘 마시던 라테에 샷을 추가해 주문하고, 니나와 바쁜 한 주 이야기를 나누세요.',
   -5, 9, 10, 'food,order,coffee', 'priya'),
  ('pr_d1_priorities', 'Aligning on priorities with Maya', '마야와 우선순위 맞추기', 'office_manager', 'maya', 1, 1, '08:30', '12:00', NULL,
   'Before standup, agree with Maya on what matters most this sprint: the must-have, the nice-to-have, and a light load for the new developer.', '스탠드업 전에 마야와 이번 스프린트에서 가장 중요한 것을 맞추세요. 꼭 해야 할 것, 있으면 좋은 것, 그리고 신입의 업무량까지.',
   0, 0, 20, 'meeting,manager,planning', 'priya'),
  ('pr_d1_standup', 'Running standup, welcoming Jun', '스탠드업 진행과 준 환영하기', 'office_meeting', 'derek', 1, 1, '09:30', '12:30', NULL,
   'Run the daily standup: start on time, welcome the new developer, clear his blocker, stop a side discussion, and finish in fifteen minutes.', '데일리 스탠드업을 진행하세요. 제시간에 시작하고, 새 개발자를 환영하고, 막힌 점을 풀어 주고, 옆길로 새는 이야기를 끊고, 15분 안에 끝내세요.',
   0, 0, 30, 'meeting,standup,facilitation', 'priya'),
  ('pr_d1_room', 'Booking the meeting room', '회의실 예약하기', 'office_lobby', 'tom', 1, 1, '12:30', '17:30', NULL,
   'Ask Tom at the front desk to book the meeting room for sprint planning, make the standup a recurring booking, and check the speakerphone.', '프런트의 톰에게 스프린트 플래닝용 회의실 예약을 부탁하고, 스탠드업을 반복 예약으로 바꾸고, 스피커폰도 확인해 달라고 하세요.',
   0, 0, 40, 'office,booking,scheduling', 'priya');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_d2_find_time', 'Finding a time with Jun', '준과 시간 맞추기', 'office_desk', 'jun', 2, 2, '10:00', '12:59', NULL,
   'You want to go over the checkout designs with Jun at one, but he has an IT appointment. Find a new time and send the invite.', '준과 한 시에 결제 화면 디자인을 보고 싶은데, 준에게 IT 예약이 있습니다. 다른 시간을 찾고 초대장을 보내세요.',
   0, 0, 10, 'meeting,scheduling', 'priya'),
  ('pr_d2_design', 'Design trade-offs with Derek', '데릭과 디자인 절충하기', 'office_desk_team', 'derek', 2, 2, '14:30', '18:30', NULL,
   'Derek has concerns about the new checkout design. Listen, ask for a simpler version, weigh the trade-off, and get the decision written down.', '데릭이 새 결제 화면 디자인을 걱정합니다. 잘 듣고, 더 단순한 안을 묻고, 장단점을 따져 보고, 결정을 글로 남기게 하세요.',
   0, 0, 20, 'meeting,design,negotiation', 'priya'),
  ('pr_d3_one_on_one', '1:1 with Maya: asking for feedback', '마야와 1:1: 피드백 구하기', 'office_manager', 'maya', 3, 3, '08:30', '12:30', NULL,
   'In your 1:1, ask Maya for feedback on your roadmap presentation, take it well, ask for an example, and give her some feedback too.', '1:1에서 마야에게 로드맵 발표에 대한 피드백을 구하고, 잘 받아들이고, 예를 들어 달라고 하고, 마야에게도 피드백을 주세요.',
   0, 0, 10, 'meeting,manager,feedback', 'priya'),
  ('pr_d3_planning', 'Facilitating sprint planning', '스프린트 플래닝 진행하기', 'office_meeting', 'derek', 3, 3, '13:30', '16:30', NULL,
   'Lead sprint planning: explain story points to Jun, ask for estimates, find an owner for the vague refund bug, and check the team''s capacity.', '스프린트 플래닝을 이끄세요. 준에게 스토리 포인트를 설명하고, 추정치를 묻고, 애매한 환불 버그를 맡을 사람을 찾고, 팀의 수용량을 확인하세요.',
   0, 0, 20, 'meeting,planning,agile,facilitation', 'priya');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_d4_scope', 'The refund bug: what to cut', '환불 버그: 무엇을 뺄 것인가', 'office_desk_team', 'derek', 4, 4, '11:00', '16:00', NULL,
   'Jun has flagged that the refund bug will not be done by Friday. Negotiate with Derek: what ships on Friday, what moves, and the new date.', '준이 환불 버그가 금요일까지 안 끝난다고 알렸습니다. 데릭과 협상하세요. 금요일에 무엇을 내보내고, 무엇을 미루고, 새 날짜는 언제인지.',
   0, 0, 10, 'meeting,negotiation,planning', 'priya'),
  ('pr_d4_client', 'Setting expectations with the client', '고객의 기대치 조율하기', 'office_meeting', 'greg', 4, 4, '13:00', '18:00', 'pr_d4_scope',
   'Call Greg Whitfield at Summit Retail. Give him the bottom line, explain what slips and what does not, and do not overpromise.', '서밋 리테일의 그렉 휫필드에게 전화하세요. 결론부터 말하고, 무엇이 늦어지고 무엇은 그대로인지 설명하되, 지키지 못할 약속은 하지 마세요.',
   0, 0, 20, 'phone,client,meeting,negotiation', 'priya'),
  ('pr_d5_demo', 'Running the demo and the retro', '데모와 회고 진행하기', 'office_meeting', 'derek', 5, 5, '10:15', '14:00', NULL,
   'Run the sprint demo and the retrospective: invite Jun to present, park a side topic, ask what went well, take feedback, and recap the action items.', '스프린트 데모와 회고를 진행하세요. 준에게 발표를 청하고, 옆길 이야기는 잠시 미뤄 두고, 잘된 점을 묻고, 피드백을 받아들이고, 액션 아이템을 정리하세요.',
   0, 0, 10, 'meeting,demo,retro,facilitation', 'priya'),
  ('pr_d5_happy_hour', 'Happy hour at the Anchor', '앵커에서 해피아워', 'office_desk_team', 'derek', 5, 5, '15:00', '18:30', NULL,
   'Derek invites you to the team happy hour. Say yes, tell him you will be a little late, praise Jun''s first week, and take a compliment.', '데릭이 팀 해피아워에 초대합니다. 가겠다고 하고, 조금 늦는다고 알리고, 준의 첫 주를 칭찬하고, 칭찬도 기분 좋게 받으세요.',
   0, 0, 20, 'small-talk,social,invitation', 'priya');

REPLACE INTO episodes (id, title, title_ko, place, npc, day_from, day_to, time_from, time_to, requires, summary, summary_ko, reward, energy, sort, tags, hero) VALUES
  ('pr_w_brunch', 'Weekend brunch at the diner', '다이너에서 주말 브런치', 'diner_counter', 'rosa', 6, 7, '09:00', '14:30', NULL,
   'Treat yourself to brunch at the Sunny Side Diner: ask about the specials, change the toast, get the check, and leave a twenty percent tip.', '서니 사이드 다이너에서 브런치로 자신에게 한턱내세요. 스페셜을 묻고, 토스트를 바꾸고, 계산서를 받고, 팁 20퍼센트를 남기세요.',
   -22, 40, 10, 'food,order,tipping,money', 'priya'),
  ('pr_w_farmers', 'The farmers market in Seaside Park', '시사이드 공원의 파머스 마켓', 'park_bench', 'carl', 6, 7, '08:00', '18:00', NULL,
   'You run into Carl, an old friend from the park, on your way to the farmers market. Ask about the peaches, find an ATM, and talk about your week.', '파머스 마켓에 가는 길에 공원에서 알고 지내는 칼을 만납니다. 복숭아 값을 묻고, 현금 인출기를 찾고, 한 주 이야기를 나누세요.',
   0, 0, 20, 'small-talk,park,shopping', 'priya'),
  ('pr_w_grocery', 'Groceries for the week', '한 주 장보기', 'market_checkout', 'mike', 6, 7, '09:00', '21:00', NULL,
   'Check out at Fairview Market: use your own bags, catch a wrong price, hand over a coupon, and pay by credit card.', '페어뷰 마켓 계산대에서 장바구니를 쓰고, 잘못 찍힌 값을 바로잡고, 쿠폰을 내고, 신용카드로 계산하세요.',
   0, 0, 30, 'shopping,market,money', 'priya');

-- pr_d1_coffee: The usual at Nina's cart
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_coffee', 1, 'nina',
   'Nina''s coffee cart on Lake Avenue. You stop here every morning on your way in.', '레이크 애비뉴에 있는 니나의 커피 카트입니다. 출근길에 매일 아침 들르는 곳이에요.',
   'Morning, Priya! The usual?', 'Say yes: a medium oat milk latte.', '네, 귀리 우유 라테 미디엄이라고 하세요.',
   '[{"any":["latte","usual"]}]',
   'Yes, please. A medium oat milk latte.',
   '["Yes, please. A table by the window.","Yes, please. Book it for Wednesday.","Yes, please. Send me the invite."]',
   '["Say yes and name your drink: size, milk, drink.","Key words: the usual, medium oat milk latte"]', '["네라고 하고 음료를 말하세요. 크기, 우유, 음료 순서로.","핵심 단어: the usual, medium oat milk latte"]',
   'nina', 'One medium oat latte, coming up.', '귀리 우유 라테 미디엄 하나, 바로 나갑니다.'),
  ('pr_d1_coffee', 2, 'nina',
   'Nina reaches for a cup.', '니나가 컵을 집어 듭니다.',
   'Hot or iced today?', 'Say hot, and ask for an extra shot because it is a big week.', '따뜻한 걸로 하고, 중요한 한 주라서 샷을 하나 추가해 달라고 하세요.',
   '[{"all":["shot"]},{"all":["espresso"]}]',
   'Hot, please. And can I get an extra shot? It''s a big week.',
   '["Hot, please. And can I get the check?","Hot, please. And can I get a bigger room?","Hot, please. And can I get your estimate?"]',
   '["Ask with \\"Can I get …?\\" for one more shot of espresso.","Key words: extra shot, big week"]', '["\\"Can I get …?\\"으로 에스프레소 샷을 하나 더 부탁하세요.","핵심 단어: extra shot, big week"]',
   'nina', 'Uh-oh, an extra-shot kind of week. You got it.', '이런, 샷 추가가 필요한 한 주군요. 알겠어요.'),
  ('pr_d1_coffee', 3, 'nina',
   'The smell of fresh muffins comes from the cart.', '카트에서 갓 구운 머핀 냄새가 납니다.',
   'Anything to eat with that? The muffins just came out.', 'Politely say no: just the latte.', '정중하게 거절하세요. 라테만 달라고요.',
   '[{"all":["no"],"any":["thanks","thank"]},{"all":["i am good"]},{"all":["all set"]},{"all":["just the latte"]}]',
   'I''m good, thanks. Just the latte.',
   '["I''m in, thanks. Save me a seat.","I''ll take it offline, thanks.","I''d love your feedback, thanks."]',
   '["\\"I''m good\\" is a friendly way to say no, thank you.","Key words: I''m good, just the latte"]', '["\\"I''m good\\"는 괜찮다고 상냥하게 거절하는 말입니다.","핵심 단어: I''m good, just the latte"]',
   'nina', 'No problem. Maybe tomorrow.', '그럼요. 내일은 드셔 보세요.'),
  ('pr_d1_coffee', 4, 'nina',
   'You hold your card over the reader.', '카드를 단말기에 갖다 댑니다.',
   'That''s five even. Big day today?', 'Say a new developer starts today and you are running the standup at ten.', '오늘 새 개발자가 출근하고, 열 시에 스탠드업을 진행한다고 하세요.',
   '[{"any":["new developer","new hire","standup","starts today","new person","new engineer"]}]',
   'Yeah. A new developer starts today, and I''m running standup at ten.',
   '["Yeah. The peaches are four dollars a pound.","Yeah. I brought my own bags today.","Yeah. I''d like the veggie omelet."]',
   '["Say who starts today and what you are running at ten.","Key words: new developer, running standup"]', '["오늘 누가 새로 오는지, 열 시에 무엇을 진행하는지 말하세요.","핵심 단어: new developer, running standup"]',
   'nina', 'Fun! Send the new hire my way. Here''s your latte. Have a good one!', '재밌겠네요! 새로 온 분한테 여기 알려 주세요. 라테 나왔어요. 좋은 하루 보내요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d1_coffee.the_usual', 'pr_d1_coffee', 'The usual?', '늘 드시던 걸로요?', 'What a barista or server asks a regular. Answer "Yes, please" or "The usual, please."', '바리스타나 종업원이 단골에게 묻는 말입니다. "Yes, please"나 "The usual, please."로 답합니다.', 'food'),
  ('pr_d1_coffee.extra_shot', 'pr_d1_coffee', 'Can I get an extra shot?', '샷 하나 추가해 주시겠어요?', '"A shot" is one serving of espresso. "Extra" means one more than usual.', 'shot은 에스프레소 1회분입니다. extra는 평소보다 하나 더라는 뜻입니다.', 'food'),
  ('pr_d1_coffee.big_week', 'pr_d1_coffee', 'It''s a big week.', '중요한 한 주예요.', '"Big" here means important and busy: a big day, a big meeting.', '여기서 big은 중요하고 바쁘다는 뜻입니다. a big day, a big meeting처럼 씁니다.', 'small-talk'),
  ('pr_d1_coffee.im_good', 'pr_d1_coffee', 'I''m good, thanks.', '괜찮아요, 고마워요.', 'A friendly way to turn down an offer.', '권하는 것을 상냥하게 사양하는 말입니다.', 'food'),
  ('pr_d1_coffee.five_even', 'pr_d1_coffee', 'That''s five even.', '딱 5달러예요.', '"Even" means exactly, with no cents.', 'even은 센트 없이 딱 떨어진다는 뜻입니다.', 'shopping'),
  ('pr_d1_coffee.running', 'pr_d1_coffee', 'I''m running standup at ten.', '열 시에 스탠드업을 진행해요.', '"To run a meeting" means to lead it.', 'run a meeting은 회의를 진행한다는 뜻입니다.', 'meeting');

-- pr_d1_priorities: Aligning on priorities with Maya
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_priorities', 1, 'maya',
   'Maya''s office. Sunlight falls on the checklist on her desk.', '마야의 사무실입니다. 책상 위 체크리스트에 햇빛이 비칩니다.',
   'Morning, Priya. Do you have a few minutes to sync before standup?', 'Say sure, and that you wanted to align on this sprint''s priorities anyway.', '물론이라고 하고, 마침 이번 스프린트 우선순위를 맞추고 싶었다고 하세요.',
   '[{"any":["align","priorities","same page"]}]',
   'Sure. I wanted to align on this sprint''s priorities anyway.',
   '["Sure. I wanted to order the club sandwich anyway.","Sure. I wanted to pay by card anyway.","Sure. I wanted to take a rain check anyway."]',
   '["\\"To align on\\" something means to agree on it together.","Key words: align on, priorities"]', '["align on은 함께 의견을 맞춘다는 뜻입니다.","핵심 단어: align on, priorities"]',
   'maya', 'Great minds think alike. Have a seat.', '마음이 통했네요. 앉아요.'),
  ('pr_d1_priorities', 2, 'maya',
   'She opens the roadmap on her screen.', '마야가 화면에 로드맵을 띄웁니다.',
   'So, what''s the top priority for this sprint?', 'Say the top priority is the new checkout flow, because the client demo is next Monday.', '최우선은 새 결제 흐름이라고, 고객 데모가 다음 주 월요일이기 때문이라고 하세요.',
   '[{"all":["checkout"]}]',
   'Our top priority is the new checkout flow. The client demo is next Monday.',
   '["Our top priority is the farmers market. It closes at noon.","Our top priority is the happy hour. It starts at five thirty.","Our top priority is the coffee cart. It opens at six thirty."]',
   '["Start with \\"Our top priority is …\\" and give the reason.","Key words: top priority, checkout flow, client demo"]', '["\\"Our top priority is …\\"로 시작하고 이유를 덧붙이세요.","핵심 단어: top priority, checkout flow, client demo"]',
   'maya', 'Agreed. That''s the must-have.', '동의해요. 그건 꼭 해야 하는 일이죠.'),
  ('pr_d1_priorities', 3, 'maya',
   'Maya scrolls down the list.', '마야가 목록을 아래로 내립니다.',
   'What about the wish list feature? Greg keeps bringing it up.', 'Say it is a nice-to-have and you would push it to the next sprint.', '있으면 좋은 기능일 뿐이니 다음 스프린트로 미루겠다고 하세요.',
   '[{"any":["nice to have","next sprint","push it","backlog"]}]',
   'That''s a nice-to-have. I''d push it to the next sprint.',
   '["That''s a medium latte. I''d like it hot.","That''s my stop. I''d better get off here.","That''s the wrong price. I''d like a refund."]',
   '["Must-have or nice-to-have? Say when you would do it.","Key words: nice-to-have, push it to the next sprint"]', '["꼭 필요한 것인지 있으면 좋은 것인지, 그리고 언제 할지 말하세요.","핵심 단어: nice-to-have, push it to the next sprint"]',
   'maya', 'Makes sense. I''ll tell Greg it''s on the roadmap, just not yet.', '좋아요. 그렉에게는 로드맵에 있지만 아직은 아니라고 말할게요.'),
  ('pr_d1_priorities', 4, 'maya',
   'She checks one more item on her list.', '마야가 목록에서 한 가지를 더 확인합니다.',
   'One more thing. Jun, the new developer, starts today. Can you keep his load light?', 'Say of course, and that you will give him one small ticket to start with.', '물론이라고 하고, 우선 작은 티켓 하나만 주겠다고 하세요.',
   '[{"any":["small ticket","one ticket","small task","easy ticket","starter","light"]}]',
   'Of course. I''ll give him one small ticket to start with.',
   '["Of course. I''ll give him a twenty percent tip.","Of course. I''ll give him the biggest project we have.","Of course. I''ll give him a ride to the airport."]',
   '["Promise a small piece of work: \\"I''ll give him …\\".","Key words: one small ticket, to start with"]', '["작은 일을 주겠다고 약속하세요. \\"I''ll give him …\\".","핵심 단어: one small ticket, to start with"]',
   'maya', 'Perfect. Nobody should drown in week one.', '좋아요. 첫 주부터 일에 파묻히면 안 되죠.'),
  ('pr_d1_priorities', 5, 'maya',
   'It is almost ten. You stand up.', '열 시가 다 되어 갑니다. 당신은 자리에서 일어납니다.',
   'Anything you need from me?', 'Ask her to back you up if the client asks for more scope.', '고객이 범위를 더 늘려 달라고 하면 힘을 실어 달라고 부탁하세요.',
   '[{"any":["back me up","support me","scope","have my back"]}]',
   'Could you back me up if the client asks for more scope?',
   '["Could you wrap it up if the food gets cold?","Could you pick me up if the bus is late?","Could you write it down if the line is long?"]',
   '["\\"Back me up\\" means support me when someone pushes.","Key words: back me up, more scope"]', '["back me up은 누가 밀어붙일 때 내 편을 들어 달라는 뜻입니다.","핵심 단어: back me up, more scope"]',
   'maya', 'Absolutely. Send him my way. And let me know if you have any questions.', '그럼요. 저한테 넘겨요. 궁금한 게 있으면 말해 주고요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d1_priorities.sync', 'pr_d1_priorities', 'Do you have a few minutes to sync?', '잠깐 이야기 맞출 시간 있어요?', '"To sync" is to share updates quickly so everyone has the same information.', 'sync는 서로 상황을 짧게 공유해 정보를 맞추는 것입니다.', 'meeting'),
  ('pr_d1_priorities.align', 'pr_d1_priorities', 'I wanted to align on priorities.', '우선순위를 맞추고 싶었어요.', '"Align on" = come to the same understanding. Very common with managers.', 'align on은 같은 이해에 이른다는 뜻입니다. 매니저와 이야기할 때 아주 자주 씁니다.', 'meeting'),
  ('pr_d1_priorities.top_priority', 'pr_d1_priorities', 'Our top priority is the new checkout flow.', '우리의 최우선 과제는 새 결제 흐름이에요.', 'Name one top priority. If everything is a priority, nothing is.', '최우선은 하나만 말하세요. 전부 우선이면 우선순위가 없는 것과 같습니다.', 'office'),
  ('pr_d1_priorities.nice_to_have', 'pr_d1_priorities', 'That''s a nice-to-have.', '그건 있으면 좋은 정도예요.', 'The opposite of a "must-have": good, but not needed now.', 'must-have의 반대말로, 좋지만 지금 꼭 필요하지는 않다는 뜻입니다.', 'office'),
  ('pr_d1_priorities.push_it', 'pr_d1_priorities', 'I''d push it to the next sprint.', '다음 스프린트로 미루겠어요.', '"Push" = move to a later date. "I''d" makes it a suggestion.', 'push는 뒤로 미룬다는 뜻입니다. I''d를 쓰면 제안하는 말투가 됩니다.', 'meeting'),
  ('pr_d1_priorities.back_me_up', 'pr_d1_priorities', 'Could you back me up?', '제 편을 들어 주시겠어요?', 'Ask this before a hard conversation, not after.', '어려운 대화가 끝난 뒤가 아니라 시작하기 전에 부탁하세요.', 'office');

-- pr_d1_standup: Running standup, welcoming Jun
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_standup', 1, 'derek',
   'Ten o''clock sharp. The team is standing around the table in the meeting room.', '열 시 정각입니다. 팀이 회의실 탁자 주위에 서 있습니다.',
   'Morning, Priya. Everybody''s here, including Jun, the new guy.', 'Start the meeting and ask Jun to say a quick hello.', '회의를 시작하고, 준에게 짧게 인사해 달라고 하세요.',
   '[{"all":["get started"]},{"all":["let us start"]},{"all":["kick"]},{"any":["quick hello","say hello","say hi","introduce yourself"]}]',
   'Okay, let''s get started. Jun, want to say a quick hello?',
   '["Okay, let''s get the check. Jun, want to split it?","Okay, let''s call it a day. Jun, want a ride home?","Okay, let''s go to the market. Jun, want some peaches?"]',
   '["Open with \\"Let''s get started\\", then invite Jun to speak.","Key words: let''s get started, a quick hello"]', '["\\"Let''s get started\\"로 열고 준에게 말할 기회를 주세요.","핵심 단어: let''s get started, a quick hello"]',
   'jun', 'Hi, everyone. I''m Jun. I just joined as a developer. Excited to be here!', '안녕하세요, 여러분. 준입니다. 개발자로 막 입사했어요. 함께하게 되어 기쁩니다!'),
  ('pr_d1_standup', 2, 'jun',
   'Jun looks a little nervous.', '준이 조금 긴장한 것 같습니다.',
   'Sorry, how does this meeting work?', 'Explain the format: what you did yesterday, what you are doing today, and any blockers.', '형식을 설명하세요. 어제 한 일, 오늘 할 일, 그리고 막힌 점입니다.',
   '[{"all":["blockers"]},{"all":["yesterday","today"]}]',
   'It''s simple: what you did yesterday, what you''re doing today, and any blockers.',
   '["It''s simple: a medium latte, oat milk, and an extra shot.","It''s simple: tap your card, take a seat, and enjoy the ride.","It''s simple: two eggs, wheat toast, and a side of bacon."]',
   '["Three parts. The last one is what is stopping you.","Key words: yesterday, today, blockers"]', '["세 가지입니다. 마지막은 일을 막고 있는 것입니다.","핵심 단어: yesterday, today, blockers"]',
   'jun', 'Got it. Today I''m setting up my laptop and my dev environment.', '알겠습니다. 오늘은 노트북과 개발 환경을 세팅합니다.'),
  ('pr_d1_standup', 3, 'jun',
   'He glances at Derek.', '준이 데릭을 흘끗 봅니다.',
   'I do have one blocker. I don''t have access to the repository yet.', 'Ask Derek if he can help Jun with that after standup.', '데릭에게 스탠드업이 끝난 뒤 준을 도와줄 수 있는지 물어보세요.',
   '[{"all":["derek"],"any":["help","access","take care","sort"]},{"all":["after standup"]}]',
   'Derek, can you help Jun with that after standup?',
   '["Rosa, can you bring us two coffees to go?","Mike, can you ring these up one more time?","Nina, can you make that a large iced tea?"]',
   '["Give the blocker an owner: name the person and the time.","Key words: Derek, help, after standup"]', '["막힌 점에 담당자를 정하세요. 사람 이름과 시점을 말합니다.","핵심 단어: Derek, help, after standup"]',
   'derek', 'Sure thing. I''ll get him access right after this.', '그럼요. 끝나자마자 권한을 받게 해 줄게요.'),
  ('pr_d1_standup', 4, 'derek',
   'Derek leans on the table. He is just getting started.', '데릭이 탁자에 몸을 기댑니다. 이야기가 길어질 기세입니다.',
   'While we''re all here: I think we should rewrite the payment module. I have a whole plan.', 'Politely stop him: say it is a good topic, but you want to take it offline.', '정중하게 끊으세요. 좋은 주제지만 회의 밖에서 따로 이야기하자고 하세요.',
   '[{"all":["offline"]},{"any":["park that","park it","separately","after the meeting"]}]',
   'Good topic, but let''s take that offline. Can you stay for five minutes after?',
   '["Good topic, but let''s take the bus. Can you walk for five minutes?","Good topic, but let''s take a break. Can you make more coffee?","Good topic, but let''s take the stairs. Can you carry this box?"]',
   '["\\"Take it offline\\" = talk about it outside this meeting.","Key words: good topic, take that offline"]', '["take it offline은 이 회의 밖에서 따로 이야기한다는 뜻입니다.","핵심 단어: good topic, take that offline"]',
   'derek', 'Fair enough. No rush.', '그래요. 급한 건 아니에요.'),
  ('pr_d1_standup', 5, 'derek',
   'The clock on the wall says 10:13.', '벽시계가 10시 13분을 가리킵니다.',
   'That''s everybody, I think.', 'Wrap up: say that is it for today, thank everyone, and say same time tomorrow.', '마무리하세요. 오늘은 여기까지라고 하고, 모두에게 고맙다고 한 뒤 내일 같은 시간에 보자고 하세요.',
   '[{"any":["that is it","thanks everyone","thank you everyone","same time","wrap"]}]',
   'That''s it for today. Thanks, everyone! Same time tomorrow.',
   '["Paper is fine. I''ll carry it myself.","Keep the change. Have a nice weekend!","Medium rare, with fries on the side."]',
   '["Close the meeting in three short sentences.","Key words: that''s it for today, thanks everyone, same time tomorrow"]', '["짧은 세 문장으로 회의를 닫으세요.","핵심 단어: that''s it for today, thanks everyone, same time tomorrow"]',
   'derek', 'Thirteen minutes. A new record.', '13분이네요. 신기록이에요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d1_standup.get_started', 'pr_d1_standup', 'Okay, let''s get started.', '자, 시작합시다.', 'The standard way to open a meeting. Say it at the exact start time.', '회의를 여는 가장 기본적인 말입니다. 정확히 시작 시간에 말하세요.', 'meeting'),
  ('pr_d1_standup.quick_hello', 'pr_d1_standup', 'Want to say a quick hello?', '짧게 인사할래요?', 'A relaxed way to invite a new person to introduce themselves.', '새로 온 사람에게 자기소개를 편하게 권하는 말입니다.', 'meeting'),
  ('pr_d1_standup.any_blockers', 'pr_d1_standup', 'Any blockers?', '막히는 거 있어요?', 'A blocker is anything that stops your work. The facilitator finds an owner for each one.', 'blocker는 일을 막는 모든 것입니다. 진행자는 blocker마다 해결할 사람을 정합니다.', 'meeting'),
  ('pr_d1_standup.after_standup', 'pr_d1_standup', 'Can you help Jun with that after standup?', '스탠드업 끝나고 준을 도와줄 수 있어요?', 'Standup is for finding problems, not solving them. Solve them after.', '스탠드업은 문제를 찾는 자리이지 푸는 자리가 아닙니다. 해결은 끝난 뒤에 합니다.', 'meeting'),
  ('pr_d1_standup.take_offline', 'pr_d1_standup', 'Let''s take that offline.', '그건 따로 이야기합시다.', 'A polite way to stop a side discussion. It does not mean "off the internet".', '옆길로 새는 이야기를 정중하게 끊는 말입니다. 인터넷을 끊는다는 뜻이 아닙니다.', 'meeting'),
  ('pr_d1_standup.thats_it', 'pr_d1_standup', 'That''s it for today.', '오늘은 여기까지예요.', 'Closes a meeting. Often followed by "Thanks, everyone!"', '회의를 마칠 때 하는 말입니다. 뒤에 "Thanks, everyone!"을 자주 붙입니다.', 'meeting'),
  ('pr_d1_standup.same_time', 'pr_d1_standup', 'Same time tomorrow.', '내일 같은 시간에 봐요.', 'Short for "We will meet at the same time tomorrow."', '"내일 같은 시간에 만납니다"를 줄인 말입니다.', 'meeting');

-- pr_d1_room: Booking the meeting room
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d1_room', 1, 'tom',
   'The front desk. Tom has the room calendar open on his screen.', '프런트 데스크입니다. 톰의 화면에 회의실 달력이 떠 있습니다.',
   'Hey, Priya! What can I do for you?', 'Say you would like to book the large meeting room for Wednesday afternoon.', '수요일 오후에 큰 회의실을 예약하고 싶다고 하세요.',
   '[{"any":["book","reserve"],"all":["wednesday"]}]',
   'I''d like to book the large meeting room for Wednesday afternoon.',
   '["I''d like to order the large pancakes for Wednesday afternoon.","I''d like to return these strawberries from Wednesday afternoon.","I''d like to take Wednesday afternoon off."]',
   '["\\"I''d like to book …\\" plus the room and the day.","Key words: book, large meeting room, Wednesday afternoon"]', '["\\"I''d like to book …\\" 뒤에 회의실과 요일을 말하세요.","핵심 단어: book, large meeting room, Wednesday afternoon"]',
   'tom', 'Sprint planning, right? Let me take a look.', '스프린트 플래닝이죠? 한번 볼게요.'),
  ('pr_d1_room', 2, 'tom',
   'He runs a finger down the calendar.', '톰이 손가락으로 달력을 짚어 내려갑니다.',
   'The sales team has it until two. Is two to four okay?', 'Say two to four works for you.', '두 시부터 네 시면 괜찮다고 하세요.',
   '[{"any":["works","perfect","fine","great"]}]',
   'Two to four works for me.',
   '["Two to four is when I sleep.","Two for four dollars is a good deal.","Two eggs over easy, please."]',
   '["Accept the time slot: \\"… works for me.\\"","Key words: two to four, works for me"]', '["시간대를 받아들이세요. \\"… works for me.\\"","핵심 단어: two to four, works for me"]',
   'tom', 'Done. It''s yours from two to four.', '됐어요. 두 시부터 네 시까지 쓰세요.'),
  ('pr_d1_room', 3, 'tom',
   'Tom keeps the calendar open.', '톰이 달력을 그대로 열어 둡니다.',
   'Anything else while I''m in here?', 'Ask him to make the ten o''clock standup a recurring booking, every weekday.', '열 시 스탠드업을 평일마다 반복되는 예약으로 해 달라고 하세요.',
   '[{"any":["recurring","every weekday","every day","repeat","standing"]}]',
   'Could you make the ten o''clock standup a recurring booking, every weekday?',
   '["Could you make the ten o''clock bus wait for me?","Could you make the pancakes gluten-free?","Could you make my latte extra hot?"]',
   '["A booking that repeats is a \\"recurring\\" booking.","Key words: recurring booking, every weekday"]', '["반복되는 예약은 recurring booking이라고 합니다.","핵심 단어: recurring booking, every weekday"]',
   'tom', 'You got it. Ten to ten fifteen, Monday through Friday.', '알겠어요. 월요일부터 금요일까지 10시부터 10시 15분.'),
  ('pr_d1_room', 4, 'tom',
   'Tom lowers his voice a little.', '톰이 목소리를 조금 낮춥니다.',
   'Heads-up, though: somebody keeps leaving coffee cups in that room.', 'Apologize and say you will remind the team to clean up.', '사과하고, 팀에게 뒷정리를 하라고 일러두겠다고 하세요.',
   '[{"any":["remind","clean up","tell the team","clean"]}]',
   'Sorry about that. I''ll remind the team to clean up after themselves.',
   '["Sorry about that. I''ll have the soup instead.","Sorry about that. I''ll catch the next bus.","Sorry about that. I''ll pay in cash."]',
   '["Say sorry, then say what you will do about it.","Key words: sorry about that, remind the team, clean up"]', '["미안하다고 한 뒤 어떻게 할지 말하세요.","핵심 단어: sorry about that, remind the team, clean up"]',
   'tom', 'Appreciate it. You''re the best.', '고마워요. 역시 프리야예요.'),
  ('pr_d1_room', 5, 'tom',
   'He picks up a pen.', '톰이 펜을 집어 듭니다.',
   'Do you need anything in the room? Markers, the speakerphone?', 'Ask him to make sure the speakerphone works, because you have a client call this week.', '이번 주에 고객과 통화가 있으니 스피커폰이 잘 되는지 확인해 달라고 하세요.',
   '[{"any":["speakerphone","phone","client call"]}]',
   'Could you make sure the speakerphone works? I have a client call this week.',
   '["Could you make sure the oven is off? I have a cake at home.","Could you make sure the bus stops here? I have a heavy bag.","Could you make sure the eggs are fresh? I have guests this week."]',
   '["\\"Could you make sure …?\\" asks someone to check something.","Key words: make sure, speakerphone, client call"]', '["\\"Could you make sure …?\\"는 확인해 달라고 부탁하는 말입니다.","핵심 단어: make sure, speakerphone, client call"]',
   'tom', 'I''ll test it this afternoon and leave fresh markers, too.', '오늘 오후에 시험해 보고, 새 마커도 갖다 놓을게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d1_room.book_room', 'pr_d1_room', 'I''d like to book the large meeting room.', '큰 회의실을 예약하고 싶어요.', '"Book" and "reserve" mean the same thing here.', '여기서 book과 reserve는 같은 뜻입니다.', 'office'),
  ('pr_d1_room.works_for_me', 'pr_d1_room', 'Two to four works for me.', '두 시부터 네 시면 괜찮아요.', '"… works for me" accepts a time. The question is "Does that work for you?"', '"… works for me"는 시간을 받아들이는 말입니다. 묻는 말은 "Does that work for you?"입니다.', 'meeting'),
  ('pr_d1_room.recurring', 'pr_d1_room', 'a recurring booking', '반복 예약', 'Recurring = happening again and again on a schedule: a recurring meeting.', 'recurring은 일정에 따라 되풀이된다는 뜻입니다. a recurring meeting처럼 씁니다.', 'meeting'),
  ('pr_d1_room.heads_up', 'pr_d1_room', 'Heads-up: …', '미리 말해 두는데, …', 'A friendly warning before a small problem gets bigger.', '작은 문제가 커지기 전에 미리 알려 주는 말입니다.', 'office'),
  ('pr_d1_room.clean_up', 'pr_d1_room', 'I''ll remind the team to clean up after themselves.', '팀에게 뒷정리를 하라고 일러둘게요.', '"Clean up after yourself" = leave the place as you found it.', 'clean up after yourself는 쓴 자리를 원래대로 해 둔다는 뜻입니다.', 'office'),
  ('pr_d1_room.make_sure', 'pr_d1_room', 'Could you make sure the speakerphone works?', '스피커폰이 되는지 확인해 주시겠어요?', '"Make sure" = check that something is true or ready.', 'make sure는 어떤 것이 제대로인지 확인한다는 뜻입니다.', 'office');

-- pr_d2_find_time: Finding a time with Jun
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d2_find_time', 1, 'jun',
   'After standup you stop by Jun''s desk. He is reading the team wiki.', '스탠드업이 끝나고 준의 자리에 들릅니다. 준은 팀 위키를 읽고 있습니다.',
   'Oh, hi, Priya! Did you need something?', 'Ask if he has a sec: you want to go over the checkout designs. Ask if one o''clock works.', '잠깐 시간 있는지 묻고, 결제 화면 디자인을 같이 보고 싶다고 하세요. 한 시가 괜찮은지도 물어보세요.',
   '[{"any":["does one","at one","one oclock","one work"]},{"all":["checkout"],"any":["go over","walk through","review","look at"]}]',
   'Do you have a sec? I want to go over the checkout designs with you. Does one o''clock work?',
   '["Do you have a pen? I want to sign the receipt. Does cash work?","Do you have a car? I want to go to the airport. Does six work?","Do you have a coupon? I want to buy some cheese."]',
   '["Three steps: \\"Do you have a sec?\\", the topic, then the time.","Key words: go over, checkout designs, does one o''clock work"]', '["세 단계입니다. \\"Do you have a sec?\\", 주제, 그리고 시간.","핵심 단어: go over, checkout designs, does one o''clock work"]',
   'jun', 'Sorry, I have an appointment with IT at one.', '죄송해요, 한 시에 IT 예약이 있어요.'),
  ('pr_d2_find_time', 2, 'jun',
   'Jun checks his calendar.', '준이 달력을 확인합니다.',
   'Could we move it to two o''clock instead?', 'Say two works for you and that you will send him a calendar invite.', '두 시면 괜찮다고 하고, 캘린더 초대장을 보내겠다고 하세요.',
   '[{"any":["works","invite","fine"]}]',
   'Two works for me. I''ll send you a calendar invite.',
   '["Two is too many. I''ll have just one.","Two dollars is too much. I''ll walk.","Two people are ahead of me. I''ll wait."]',
   '["Accept the time, then promise the invite.","Key words: works for me, calendar invite"]', '["시간을 받아들이고 초대장을 약속하세요.","핵심 단어: works for me, calendar invite"]',
   'jun', 'Great, thank you!', '좋아요, 고맙습니다!'),
  ('pr_d2_find_time', 3, 'jun',
   'He opens a new block on his calendar.', '준이 달력에 새 일정을 만듭니다.',
   'How long will it take? I want to block out the time.', 'Say thirty minutes should do it, and you will book the small room by the kitchen.', '30분이면 충분하고, 탕비실 옆 작은 방을 예약하겠다고 하세요.',
   '[{"any":["thirty","30","half an hour"]}]',
   'Thirty minutes should do it. I''ll book the small room by the kitchen.',
   '["Three points should do it. I''ll add it to the sprint.","Two pounds should do it. I''ll pay in cash.","One shot should do it. I''ll take it to go."]',
   '["Give the length: \\"… should do it\\" means it is enough.","Key words: thirty minutes, should do it"]', '["길이를 말하세요. \\"… should do it\\"은 그 정도면 충분하다는 뜻입니다.","핵심 단어: thirty minutes, should do it"]',
   'jun', 'Thirty minutes. Got it.', '30분. 알겠습니다.'),
  ('pr_d2_find_time', 4, 'jun',
   'Jun picks up his notebook.', '준이 공책을 집어 듭니다.',
   'Should I prepare anything?', 'Say there is no prep needed, but he could take a look at the mockups beforehand.', '준비할 건 없지만, 미리 목업을 한번 봐 두면 좋겠다고 하세요.',
   '[{"any":["mockups","mockup","no prep","take a look","beforehand"]}]',
   'No prep needed. Just take a look at the mockups beforehand if you have time.',
   '["No tip needed. Just pay at the counter on your way out.","No bag needed. Just put it in my backpack.","No sugar needed. Just a little oat milk."]',
   '["\\"No prep needed\\" + one small thing he could do before.","Key words: no prep needed, mockups, beforehand"]', '["\\"No prep needed\\"라고 하고, 미리 할 수 있는 작은 일 하나를 말하세요.","핵심 단어: no prep needed, mockups, beforehand"]',
   'jun', 'Will do. I''ll look at them before lunch.', '그럴게요. 점심 전에 볼게요.'),
  ('pr_d2_find_time', 5, 'jun',
   'He hesitates for a second.', '준이 잠깐 머뭇거립니다.',
   'And, um, what if IT runs long?', 'Say no worries: he should just send you a message and you will push it back.', '괜찮다고 하세요. 메시지만 보내면 시간을 뒤로 미루겠다고요.',
   '[{"any":["message","ping","let me know","push it","text"]}]',
   'No worries. Just shoot me a message and we''ll push it back.',
   '["No worries. Just put it on my tab and I''ll pay on Friday.","No worries. Just leave it on the porch and I''ll pick it up.","No worries. Just warm it up and I''ll eat it later."]',
   '["Tell him how to reach you and what you will do.","Key words: shoot me a message, push it back"]', '["어떻게 연락하면 되는지, 그러면 어떻게 할지 말하세요.","핵심 단어: shoot me a message, push it back"]',
   'jun', 'Thanks, Priya. I''ll keep you posted.', '고마워요, 프리야. 계속 알려 드릴게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d2_find_time.have_a_sec', 'pr_d2_find_time', 'Do you have a sec?', '잠깐 시간 있어요?', '"A sec" = a second. Ask this before you interrupt someone.', 'a sec은 a second를 줄인 말입니다. 남의 일을 끊기 전에 물어보세요.', 'office'),
  ('pr_d2_find_time.go_over', 'pr_d2_find_time', 'I want to go over the checkout designs with you.', '결제 화면 디자인을 같이 살펴보고 싶어요.', '"Go over" = look at something together, step by step.', 'go over는 함께 차근차근 살펴본다는 뜻입니다.', 'meeting'),
  ('pr_d2_find_time.does_one_work', 'pr_d2_find_time', 'Does one o''clock work?', '한 시 괜찮아요?', 'The easiest way to suggest a time. Also: "Does that work for you?"', '시간을 제안하는 가장 쉬운 방법입니다. "Does that work for you?"도 씁니다.', 'meeting'),
  ('pr_d2_find_time.send_invite', 'pr_d2_find_time', 'I''ll send you a calendar invite.', '캘린더 초대장을 보낼게요.', 'At American offices a meeting is not real until it is on the calendar.', '미국 회사에서는 달력에 올라가야 비로소 회의가 잡힌 것입니다.', 'meeting'),
  ('pr_d2_find_time.should_do_it', 'pr_d2_find_time', 'Thirty minutes should do it.', '30분이면 될 거예요.', '"… should do it" = that will be enough.', '"… should do it"은 그 정도면 충분하다는 뜻입니다.', 'meeting'),
  ('pr_d2_find_time.no_prep', 'pr_d2_find_time', 'No prep needed.', '준비할 건 없어요.', '"Prep" is short for preparation.', 'prep은 preparation을 줄인 말입니다.', 'meeting'),
  ('pr_d2_find_time.push_back', 'pr_d2_find_time', 'We''ll push it back.', '시간을 뒤로 미룰게요.', '"Push back" a meeting = move it later. "Move up" = make it earlier.', '회의를 push back하면 뒤로 미루는 것이고, move up하면 앞당기는 것입니다.', 'meeting');

-- pr_d2_design: Design trade-offs with Derek
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d2_design', 1, 'derek',
   'After the design review with Jun, Derek waves you over to his desk.', '준과 디자인 리뷰를 마친 뒤, 데릭이 자기 자리로 오라고 손짓합니다.',
   'So, I looked at the new checkout mockups. They look great, but honestly, I have some concerns.', 'Say you are all ears and ask what his concerns are.', '잘 듣겠다고 하고, 무엇이 걱정인지 물어보세요.',
   '[{"any":["concerns","all ears","worried","worries"]}]',
   'I''m all ears. What are your concerns?',
   '["I''m all set. Where is the exit?","I''m full. What are your desserts?","I''m lost. Where is the bus stop?"]',
   '["\\"I''m all ears\\" = I am listening carefully.","Key words: all ears, concerns"]', '["\\"I''m all ears\\"는 귀 기울여 듣겠다는 뜻입니다.","핵심 단어: all ears, concerns"]',
   'derek', 'Okay. It''s the one-page layout.', '좋아요. 문제는 한 페이지짜리 레이아웃이에요.'),
  ('pr_d2_design', 2, 'derek',
   'He turns his monitor toward you.', '데릭이 모니터를 당신 쪽으로 돌립니다.',
   'Putting everything on one page means rewriting the address form. That''s two weeks, easy.', 'Ask if there is a simpler version that gets you most of the way there.', '대부분의 효과를 얻을 수 있는 더 단순한 안이 있는지 물어보세요.',
   '[{"any":["simpler","easier","smaller version","lighter","most of the way"]}]',
   'Is there a simpler version that gets us most of the way there?',
   '["Is there a bus that gets us to the airport?","Is there a table for two by the window?","Is there a sale on strawberries this week?"]',
   '["Do not say no. Ask for a smaller option.","Key words: a simpler version, most of the way there"]', '["안 된다고 하지 말고, 더 작은 선택지를 물어보세요.","핵심 단어: a simpler version, most of the way there"]',
   'derek', 'We could keep the old form and tuck it into a section that opens and closes. Three days, maybe.', '기존 양식을 그대로 두고 접었다 펴는 영역에 넣을 수 있어요. 사흘쯤 걸릴 거예요.'),
  ('pr_d2_design', 3, 'derek',
   'Two weeks against three days. You like the sound of that.', '2주 대 사흘. 듣기에 좋습니다.',
   'It''s not perfect, though.', 'Say you like the idea and ask what the trade-off is.', '그 생각이 마음에 든다고 하고, 대신 잃는 것이 무엇인지 물어보세요.',
   '[{"any":["trade off","tradeoff","downside","catch"]}]',
   'I like that. What''s the trade-off?',
   '["I like that. What''s the soup of the day?","I like that. What''s the bus fare?","I like that. What''s your phone number?"]',
   '["Every shortcut costs something. Ask what.","Key words: I like that, trade-off"]', '["지름길에는 대가가 있습니다. 그것이 무엇인지 물어보세요.","핵심 단어: I like that, trade-off"]',
   'derek', 'It won''t look as slick on mobile. Users have to tap one more time.', '모바일에서는 덜 매끈해 보일 거예요. 사용자가 한 번 더 눌러야 하고요.'),
  ('pr_d2_design', 4, 'derek',
   'One more tap. The client demo is on Monday.', '한 번 더 누르기. 고객 데모는 월요일입니다.',
   'Can you live with that?', 'Say you can live with that, and you want to go with the simpler version for now.', '그 정도는 감수할 수 있다고 하고, 일단 단순한 안으로 가자고 하세요.',
   '[{"any":["live with","go with","simpler version"]}]',
   'I can live with that. Let''s go with the simpler version for now.',
   '["I can walk from here. Let''s meet at the fountain at noon.","I can pay for that. Let''s split the rest.","I can carry that. Let''s take the stairs."]',
   '["Accept the downside, then decide: \\"Let''s go with …\\".","Key words: I can live with that, let''s go with"]', '["단점을 받아들이고 결정하세요. \\"Let''s go with …\\".","핵심 단어: I can live with that, let''s go with"]',
   'derek', 'Cool. Good call.', '좋아요. 잘 정했어요.'),
  ('pr_d2_design', 5, 'derek',
   'Derek opens the design doc.', '데릭이 디자인 문서를 엽니다.',
   'Want me to write that up?', 'Say yes, and ask him to add it to the design doc so everyone is on the same page.', '네라고 하고, 모두가 같은 내용을 알 수 있게 디자인 문서에 넣어 달라고 하세요.',
   '[{"any":["design doc","same page","document","doc"]}]',
   'Yes, please. Could you add it to the design doc so we''re all on the same page?',
   '["Yes, please. Could you add it to my bill?","Yes, please. Could you add cheese and bacon?","Yes, please. Could you add some ice?"]',
   '["A decision that is not written down gets forgotten.","Key words: add it to the design doc, on the same page"]', '["적어 두지 않은 결정은 잊힙니다.","핵심 단어: add it to the design doc, on the same page"]',
   'derek', 'Will do. It''ll be in there by end of day.', '그럴게요. 오늘 퇴근 전까지 넣어 둘게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d2_design.concerns', 'pr_d2_design', 'I have some concerns.', '걱정되는 점이 좀 있어요.', 'A calm, professional way to disagree. Softer than "I don''t like it."', '반대 의견을 차분하고 프로답게 꺼내는 말입니다. "I don''t like it."보다 부드럽습니다.', 'meeting'),
  ('pr_d2_design.all_ears', 'pr_d2_design', 'I''m all ears.', '잘 듣고 있어요. / 말해 봐요.', 'Shows you really want to hear the other person''s view.', '상대의 의견을 정말 듣고 싶다는 뜻을 나타냅니다.', 'office'),
  ('pr_d2_design.simpler_version', 'pr_d2_design', 'Is there a simpler version that gets us most of the way there?', '대부분의 효과를 내는 더 단순한 안이 있을까요?', 'A product manager''s best question: most of the value for a part of the work.', '프로덕트 매니저의 가장 좋은 질문입니다. 일은 일부만 하고 가치는 대부분 얻자는 뜻입니다.', 'meeting'),
  ('pr_d2_design.trade_off', 'pr_d2_design', 'What''s the trade-off?', '대신 잃는 게 뭐예요?', 'A trade-off is what you give up to get something else.', 'trade-off는 하나를 얻으려고 포기하는 것입니다.', 'meeting'),
  ('pr_d2_design.live_with', 'pr_d2_design', 'I can live with that.', '그 정도는 감수할 수 있어요.', 'You accept something that is not perfect.', '완벽하지는 않지만 받아들인다는 뜻입니다.', 'meeting'),
  ('pr_d2_design.go_with', 'pr_d2_design', 'Let''s go with the simpler version for now.', '일단 단순한 안으로 갑시다.', '"Go with" = choose. "For now" leaves the door open to change it later.', 'go with는 고른다는 뜻입니다. for now는 나중에 바꿀 여지를 남깁니다.', 'meeting'),
  ('pr_d2_design.same_page', 'pr_d2_design', 'so we''re all on the same page', '모두가 같은 내용을 알도록', '"On the same page" = having the same understanding.', 'on the same page는 같은 이해를 공유한다는 뜻입니다.', 'office');

-- pr_d3_one_on_one: 1:1 with Maya: asking for feedback
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d3_one_on_one', 1, 'maya',
   'Rain taps on the window of Maya''s office. You shake out your umbrella at the door.', '마야의 사무실 창문에 빗방울이 떨어집니다. 당신은 문 앞에서 우산을 텁니다.',
   'Come on in. Is it still raining out there?', 'Say it has been on and off all morning, and it is a good thing you brought an umbrella.', '아침 내내 오락가락한다고, 우산을 가져오길 잘했다고 하세요.',
   '[{"any":["umbrella","on and off","raining","pouring"]}]',
   'It''s been on and off all morning. Good thing I brought an umbrella.',
   '["It''s been closed all morning. Good thing I ate at home.","It''s been on sale all week. Good thing I had a coupon.","It''s been broken all month. Good thing I called IT."]',
   '["Rain that starts and stops is \\"on and off\\".","Key words: on and off, good thing, umbrella"]', '["오다 말다 하는 비는 on and off라고 합니다.","핵심 단어: on and off, good thing, umbrella"]',
   'maya', 'Smart. I left mine in the car, of course.', '현명하네요. 저는 당연히 차에 두고 왔어요.'),
  ('pr_d3_one_on_one', 2, 'maya',
   'Maya closes her laptop to give you her full attention.', '마야가 노트북을 덮고 당신에게 집중합니다.',
   'So, what''s on your mind?', 'Say you would love her feedback on your roadmap presentation from last week.', '지난주 로드맵 발표에 대한 피드백을 듣고 싶다고 하세요.',
   '[{"all":["feedback"]}]',
   'I''d love your feedback on my roadmap presentation from last week.',
   '["I''d love your recipe for the peach pie from last week.","I''d love a refill on my coffee.","I''d love a seat on the patio."]',
   '["Ask directly: \\"I''d love your feedback on …\\".","Key words: I''d love your feedback, roadmap presentation"]', '["직접 부탁하세요. \\"I''d love your feedback on …\\".","핵심 단어: I''d love your feedback, roadmap presentation"]',
   'maya', 'Overall, it was strong. The story was clear. One thing: there were a lot of slides, and you ran out of time for questions.', '전체적으로 좋았어요. 흐름이 분명했어요. 한 가지, 슬라이드가 많아서 질문받을 시간이 없었어요.'),
  ('pr_d3_one_on_one', 3, 'maya',
   'It stings a little. You are the one who keeps meetings on time.', '조금 따끔합니다. 회의 시간을 지키는 사람이 바로 당신이니까요.',
   'Does that sound fair?', 'Say that is fair, and that you will cut it down and leave time for Q&A.', '맞는 말이라고 하고, 분량을 줄여 질의응답 시간을 남기겠다고 하세요.',
   '[{"any":["fair","good point","cut it","cut","leave time","fewer slides"]}]',
   'That''s fair. I''ll cut it down and leave time for Q&A next time.',
   '["That''s mine. I''ll take it to go.","That''s expensive. I''ll put one back.","That''s my bus. I''ll see you tomorrow."]',
   '["Do not defend yourself. Agree, then say what you will change.","Key words: that''s fair, cut it down, leave time for Q&A"]', '["변명하지 마세요. 동의하고, 무엇을 바꿀지 말하세요.","핵심 단어: that''s fair, cut it down, leave time for Q&A"]',
   'maya', 'Great. Also, try leading with the bottom line.', '좋아요. 그리고 결론부터 말해 보세요.'),
  ('pr_d3_one_on_one', 4, 'maya',
   '"The bottom line"? You want to be sure you understand.', '"결론부터"? 정확히 이해하고 싶습니다.',
   'Executives want the ask first, and the details second.', 'Ask her to give you an example of what she means.', '무슨 뜻인지 예를 하나 들어 달라고 하세요.',
   '[{"any":["example","for instance"]}]',
   'Could you give me an example of what you mean?',
   '["Could you give me a ride to the office?","Could you give me a bag for these apples?","Could you give me a table near the door?"]',
   '["When feedback is general, ask for one real case.","Key words: give me an example, what you mean"]', '["피드백이 막연하면 실제 사례를 하나 물어보세요.","핵심 단어: give me an example, what you mean"]',
   'maya', 'Sure. Start with: "We need two more weeks for checkout, and here''s why." Then the slides.', '그럼요. "결제 기능에 2주가 더 필요합니다. 이유는 이렇습니다."로 시작하고, 슬라이드는 그다음에요.'),
  ('pr_d3_one_on_one', 5, 'maya',
   'You write it down. Maya smiles.', '당신은 받아 적습니다. 마야가 미소 짓습니다.',
   'Now your turn. Is there anything I could be doing better?', 'Say it would help if she looped you in on client emails earlier.', '고객 이메일에 더 일찍 끼워 주면 도움이 되겠다고 하세요.',
   '[{"any":["loop me in","looped me in","looped","cc","copy me","earlier","sooner"]}]',
   'It would help if you looped me in on client emails earlier.',
   '["It would help if you held the elevator.","It would help if you sliced the bread.","It would help if you had exact change."]',
   '["Soft and clear: \\"It would help if you …\\".","Key words: it would help if, looped me in, earlier"]', '["부드럽지만 분명하게: \\"It would help if you …\\".","핵심 단어: it would help if, looped me in, earlier"]',
   'maya', 'That''s fair. I''ll cc you from now on. Let me know if you have any questions.', '맞는 말이에요. 앞으로는 참조로 넣을게요. 궁금한 게 있으면 말해 줘요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d3_one_on_one.on_your_mind', 'pr_d3_one_on_one', 'What''s on your mind?', '무슨 이야기를 하고 싶어요?', 'How a manager opens a 1:1. You choose the topic.', '매니저가 1:1을 여는 말입니다. 주제는 당신이 고릅니다.', 'meeting'),
  ('pr_d3_one_on_one.love_feedback', 'pr_d3_one_on_one', 'I''d love your feedback on my presentation.', '제 발표에 대해 피드백을 듣고 싶어요.', 'Asking for feedback shows confidence, not weakness.', '피드백을 구하는 것은 약점이 아니라 자신감의 표시입니다.', 'office'),
  ('pr_d3_one_on_one.thats_fair', 'pr_d3_one_on_one', 'That''s fair.', '맞는 말이에요.', 'Accepts criticism calmly. Follow it with what you will change.', '비판을 차분히 받아들이는 말입니다. 뒤에 무엇을 바꿀지 덧붙이세요.', 'office'),
  ('pr_d3_one_on_one.bottom_line', 'pr_d3_one_on_one', 'Lead with the bottom line.', '결론부터 말하세요.', 'The bottom line is the main point or result. Busy people want it first.', 'bottom line은 핵심이나 결론입니다. 바쁜 사람은 그것부터 듣고 싶어 합니다.', 'meeting'),
  ('pr_d3_one_on_one.example', 'pr_d3_one_on_one', 'Could you give me an example of what you mean?', '무슨 뜻인지 예를 들어 주시겠어요?', 'Turns general feedback into something you can act on.', '막연한 피드백을 실행할 수 있는 것으로 바꿔 줍니다.', 'office'),
  ('pr_d3_one_on_one.it_would_help', 'pr_d3_one_on_one', 'It would help if you looped me in earlier.', '더 일찍 끼워 주시면 도움이 되겠어요.', '"It would help if …" gives feedback without blaming. "Loop in" = include someone.', '"It would help if …"는 탓하지 않고 피드백을 주는 표현입니다. loop in은 누군가를 끼워 준다는 뜻입니다.', 'office'),
  ('pr_d3_one_on_one.on_and_off', 'pr_d3_one_on_one', 'It''s been raining on and off.', '비가 오락가락해요.', '"On and off" = starting and stopping again and again.', 'on and off는 되풀이해서 시작했다 멈췄다 한다는 뜻입니다.', 'small-talk');

-- pr_d3_planning: Facilitating sprint planning
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d3_planning', 1, 'derek',
   'Two o''clock. Wet umbrellas are drying in the corner of the meeting room.', '두 시입니다. 회의실 구석에서 젖은 우산들이 마르고 있습니다.',
   'We''re all here. The floor is yours.', 'Welcome everyone to sprint planning and say you will go through the tickets and estimate each one.', '스프린트 플래닝에 온 것을 환영하고, 티켓을 하나씩 보면서 추정하겠다고 하세요.',
   '[{"any":["estimate","go through","tickets"]}]',
   'Welcome to sprint planning. We''ll go through the tickets and estimate each one.',
   '["Welcome to the Sunny Side Diner. We''ll seat you in just a minute.","Welcome to Fairview Market. We''ll be closing in ten minutes.","Welcome to the building. We''ll need to see your badge."]',
   '["Say what the meeting is and what you will do in it.","Key words: sprint planning, go through the tickets, estimate"]', '["무슨 회의인지, 무엇을 할지 말하세요.","핵심 단어: sprint planning, go through the tickets, estimate"]',
   'jun', 'Quick question: what does one story point mean for this team?', '잠깐 질문인데요, 이 팀에서 스토리 포인트 1은 무슨 뜻이에요?'),
  ('pr_d3_planning', 2, 'jun',
   'It is Jun''s first planning meeting.', '준에게는 첫 플래닝 회의입니다.',
   'So a point isn''t the same as an hour?', 'Say right: it is about effort and complexity, not hours.', '맞다고 하고, 시간이 아니라 노력과 복잡도를 뜻한다고 하세요.',
   '[{"any":["effort","complexity","not hours"]}]',
   'Right. It''s about effort and complexity, not hours. A one is tiny, an eight is big.',
   '["Right. It''s about four dollars a pound, not five.","Right. It''s about ten minutes on foot, not twenty.","Right. It''s about time for lunch."]',
   '["A point measures how hard the work is, not how long.","Key words: effort, complexity, not hours"]', '["포인트는 걸리는 시간이 아니라 일이 얼마나 어려운지를 잽니다.","핵심 단어: effort, complexity, not hours"]',
   'jun', 'That makes sense. Thanks.', '이해됐어요. 고맙습니다.'),
  ('pr_d3_planning', 3, 'derek',
   'The first ticket is on the screen: a "save card for later" checkbox at checkout.', '첫 티켓이 화면에 떠 있습니다. 결제 화면의 "카드 저장" 체크박스입니다.',
   'I''d call that one a three.', 'Ask Jun what he would estimate.', '준에게 얼마로 추정하는지 물어보세요.',
   '[{"all":["jun"],"any":["estimate","think","say","points","number"]},{"all":["what would you estimate"]}]',
   'Jun, what would you estimate?',
   '["Rosa, what would you recommend?","Tom, where would you park?","Nina, which muffin would you pick?"]',
   '["Bring in the quiet person by name.","Key words: Jun, what would you estimate"]', '["조용한 사람을 이름으로 불러 참여시키세요.","핵심 단어: Jun, what would you estimate"]',
   'jun', 'I''d say a three. The UI is simple, but we need to test it carefully.', '3이라고 생각해요. 화면은 단순하지만 꼼꼼히 테스트해야 하니까요.'),
  ('pr_d3_planning', 4, 'derek',
   'Three it is. The next ticket comes up.', '3으로 정했습니다. 다음 티켓이 뜹니다.',
   'Next is the refund bug. The ticket''s pretty vague.', 'Ask who has the capacity to take it.', '누가 맡을 여력이 있는지 물어보세요.',
   '[{"any":["capacity","who wants","who can","volunteers","volunteer","anybody want","anyone want"]}]',
   'Who has the capacity to take this one?',
   '["Who has the keys to the supply closet?","Who has the next number in line?","Who ordered the veggie omelet?"]',
   '["Ask for an owner without pointing at anyone.","Key words: who has the capacity, take this one"]', '["누구를 지목하지 말고 맡을 사람을 구하세요.","핵심 단어: who has the capacity, take this one"]',
   'jun', 'I can take it, but I''ll need more details first.', '제가 맡을 수 있어요. 다만 먼저 자세한 내용이 필요해요.'),
  ('pr_d3_planning', 5, 'jun',
   'Jun has his pen ready.', '준이 펜을 들고 기다립니다.',
   'Could you add the customer''s steps to the ticket?', 'Say sure, you will add the steps to reproduce it by end of day.', '그러겠다고 하고, 오늘 퇴근 전까지 재현 단계를 넣겠다고 하세요.',
   '[{"any":["steps","end of day","eod","by tonight"]}]',
   'Sure. I''ll add the steps to reproduce it by end of day.',
   '["Sure. I''ll add a side of fries.","Sure. I''ll add you to the guest list.","Sure. I''ll add a twenty percent tip."]',
   '["Promise what and by when.","Key words: steps to reproduce, by end of day"]', '["무엇을 언제까지 할지 약속하세요.","핵심 단어: steps to reproduce, by end of day"]',
   'jun', 'Perfect. Thank you!', '좋아요. 고맙습니다!'),
  ('pr_d3_planning', 6, 'derek',
   'Derek adds up the numbers on the whiteboard.', '데릭이 화이트보드의 숫자를 더합니다.',
   'That''s thirty-four points. We usually finish about thirty-five.', 'Say then you are at capacity, and ask if anyone feels it is too much.', '그럼 수용량이 찼다고 하고, 너무 많다고 느끼는 사람이 있는지 물어보세요.',
   '[{"any":["at capacity","capacity","too much","overcommitted"]}]',
   'Then we''re at capacity. Does anyone feel like this is too much?',
   '["Then we''re at the wrong gate. Does anyone have the tickets?","Then we''re out of milk. Does anyone want tea?","Then we''re closed on Sunday."]',
   '["Check before you commit: is the sprint too full?","Key words: at capacity, too much"]', '["확정하기 전에 확인하세요. 스프린트가 너무 찼나요?","핵심 단어: at capacity, too much"]',
   'derek', 'Looks doable to me. Let''s lock it in.', '할 만해 보여요. 이대로 확정하죠.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d3_planning.floor_is_yours', 'pr_d3_planning', 'The floor is yours.', '이제 말씀하세요. / 진행하세요.', 'Said to hand the meeting to the next speaker.', '다음 발언자에게 회의를 넘길 때 하는 말입니다.', 'meeting'),
  ('pr_d3_planning.go_through', 'pr_d3_planning', 'We''ll go through the tickets and estimate each one.', '티켓을 하나씩 보면서 추정할게요.', '"Go through" = look at the items of a list one by one.', 'go through는 목록의 항목을 하나씩 살펴본다는 뜻입니다.', 'meeting'),
  ('pr_d3_planning.effort_not_hours', 'pr_d3_planning', 'It''s about effort and complexity, not hours.', '시간이 아니라 노력과 복잡도를 뜻해요.', 'How most teams explain story points.', '대부분의 팀이 스토리 포인트를 설명하는 방식입니다.', 'meeting'),
  ('pr_d3_planning.what_estimate', 'pr_d3_planning', 'What would you estimate?', '얼마로 추정해요?', 'Ask people by name, so the quiet ones speak too.', '이름을 불러 물으면 조용한 사람도 말하게 됩니다.', 'meeting'),
  ('pr_d3_planning.capacity', 'pr_d3_planning', 'Who has the capacity to take this one?', '누가 이걸 맡을 여력이 있어요?', 'Capacity = how much work a person or team can take on.', 'capacity는 사람이나 팀이 맡을 수 있는 일의 양입니다.', 'meeting'),
  ('pr_d3_planning.end_of_day', 'pr_d3_planning', 'by end of day', '오늘 퇴근 전까지', 'Often written EOD. It means before you leave work today.', 'EOD로 자주 줄여 씁니다. 오늘 퇴근하기 전까지라는 뜻입니다.', 'office'),
  ('pr_d3_planning.lock_it_in', 'pr_d3_planning', 'Let''s lock it in.', '이대로 확정합시다.', 'To make a plan final.', '계획을 최종 확정한다는 뜻입니다.', 'meeting');

-- pr_d4_scope: The refund bug: what to cut
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d4_scope', 1, 'derek',
   'A gray, cool morning. Jun has just told you the refund bug is taking longer than he expected.', '흐리고 선선한 아침입니다. 준이 방금 환불 버그가 예상보다 오래 걸린다고 알려 왔습니다.',
   'Hey. I heard about the refund bug. Jun''s deep in the legacy code, huh?', 'Say he flagged it early, which you appreciate, and ask for Derek''s read on it.', '준이 일찍 알려 줘서 고맙다고 하고, 데릭은 상황을 어떻게 보는지 물어보세요.',
   '[{"any":["your read","your take","what do you think","how bad"]}]',
   'Yeah. He flagged it early, which I appreciate. What''s your read on it?',
   '["Yeah. He ordered early, which I appreciate. What''s for dessert?","Yeah. He paid in cash, which I appreciate. Where''s the receipt?","Yeah. He left early. Where''s his umbrella?"]',
   '["\\"What''s your read on it?\\" asks for an expert''s opinion.","Key words: flagged it early, what''s your read"]', '["\\"What''s your read on it?\\"은 전문가의 판단을 묻는 말입니다.","핵심 단어: flagged it early, what''s your read"]',
   'derek', 'It''s two bugs, really. Card refunds and gift card refunds. No tests on either one.', '사실은 버그가 두 개예요. 카드 환불과 기프트 카드 환불. 둘 다 테스트가 없어요.'),
  ('pr_d4_scope', 2, 'derek',
   'Two bugs, not one. You need a date.', '버그가 하나가 아니라 둘입니다. 날짜가 필요합니다.',
   'So it''s more work than the ticket says.', 'Ask what the ETA is if the team fixes both.', '둘 다 고치면 언제 끝날지 물어보세요.',
   '[{"any":["eta","how long","when would","when will","when can"]}]',
   'What''s the ETA if we fix both?',
   '["What''s the fare if we take the bus?","What''s the total if we split it?","What''s the special if we sit at the counter?"]',
   '["ETA = estimated time of arrival: when will it be done?","Key words: what''s the ETA, fix both"]', '["ETA는 예상 완료 시점입니다. 언제 끝나는지 물어보세요.","핵심 단어: what''s the ETA, fix both"]',
   'derek', 'Both? End of next week, realistically.', '둘 다요? 현실적으로 다음 주 말이에요.'),
  ('pr_d4_scope', 3, 'derek',
   'The client demo is on Monday. End of next week is too late.', '고객 데모는 월요일입니다. 다음 주 말은 너무 늦습니다.',
   'I know that''s not what you wanted to hear.', 'Say the client demo is on Monday, and ask what it would take to ship the card fix by Friday.', '고객 데모가 월요일이라고 하고, 카드 환불 수정을 금요일까지 내보내려면 무엇이 필요한지 물어보세요.',
   '[{"all":["what would it take"]},{"all":["friday"],"any":["ship","card","fix","release"]}]',
   'The client demo is on Monday. What would it take to ship the card fix by Friday?',
   '["The farmers market is on Saturday. What would you like me to bring?","The diner is on Lake Avenue. What would you like to eat?","The bus is on time. What would you like to do downtown?"]',
   '["Do not demand. Ask \\"What would it take to …?\\"","Key words: what would it take, ship, by Friday"]', '["요구하지 말고 \\"What would it take to …?\\"로 물어보세요.","핵심 단어: what would it take, ship, by Friday"]',
   'derek', 'If I pair with Jun and we leave the gift cards for later, Friday''s doable.', '제가 준과 같이 작업하고 기프트 카드를 뒤로 미루면 금요일은 가능해요.'),
  ('pr_d4_scope', 4, 'derek',
   'That is a plan you can take to the client.', '고객에게 가져갈 수 있는 계획입니다.',
   'But the gift card part needs a new date.', 'Propose card refunds on Friday and gift cards by next Wednesday, and ask if that works for him.', '카드 환불은 금요일, 기프트 카드는 다음 주 수요일까지로 제안하고, 괜찮은지 물어보세요.',
   '[{"all":["wednesday"]},{"any":["does that work","work for you"]}]',
   'Let''s do card refunds on Friday and gift cards by next Wednesday. Does that work for you?',
   '["Let''s do pancakes on Saturday and tacos on Sunday. Is the diner open?","Let''s do coffee on Monday. Is the cart open at seven?","Let''s do lunch. Is noon too early?"]',
   '["Offer two dates, then check: \\"Does that work for you?\\"","Key words: card refunds on Friday, next Wednesday, does that work for you"]', '["날짜 두 개를 제안한 뒤 확인하세요. \\"Does that work for you?\\"","핵심 단어: card refunds on Friday, next Wednesday, does that work for you"]',
   'derek', 'Wednesday works. But then I have to drop the search filter ticket.', '수요일 괜찮아요. 그런데 그러려면 검색 필터 티켓은 내려놓아야 해요.'),
  ('pr_d4_scope', 5, 'derek',
   'Something has to give. You decide quickly.', '무언가는 포기해야 합니다. 당신은 빠르게 결정합니다.',
   'Are you okay with that?', 'Say that is fine: you will move it to the next sprint and let the client know.', '괜찮다고 하세요. 그 티켓은 다음 스프린트로 옮기고 고객에게 알리겠다고요.',
   '[{"any":["next sprint","move it","push it","backlog"]}]',
   'That''s fine. I''ll move it to the next sprint and let the client know.',
   '["That''s fine. I''ll take the window seat and let you sleep.","That''s fine. I''ll have the salad and skip dessert.","That''s fine. I''ll walk home and get some air."]',
   '["Make the cut, and say who you will tell.","Key words: move it to the next sprint, let the client know"]', '["뺄 것을 정하고, 누구에게 알릴지 말하세요.","핵심 단어: move it to the next sprint, let the client know"]',
   'derek', 'Thanks for not asking for everything at once. I''ll grab Jun.', '한꺼번에 다 해 달라고 하지 않아서 고마워요. 준을 데려올게요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d4_scope.flagged', 'pr_d4_scope', 'He flagged it early.', '그가 일찍 알려 줬어요.', '"Flag" = point out a problem so people notice. Flagging early is praised.', 'flag는 문제를 알아차리도록 알린다는 뜻입니다. 일찍 알리면 칭찬받습니다.', 'office'),
  ('pr_d4_scope.your_read', 'pr_d4_scope', 'What''s your read on it?', '상황을 어떻게 보세요?', 'Asks for someone''s judgment of a situation.', '상황에 대한 상대의 판단을 묻는 말입니다.', 'meeting'),
  ('pr_d4_scope.eta', 'pr_d4_scope', 'What''s the ETA?', '언제쯤 끝나요?', 'ETA = estimated time of arrival. At work: when will it be done?', 'ETA는 estimated time of arrival의 약자입니다. 직장에서는 언제 끝나는지를 뜻합니다.', 'office'),
  ('pr_d4_scope.what_would_it_take', 'pr_d4_scope', 'What would it take to ship the card fix by Friday?', '카드 환불 수정을 금요일까지 내보내려면 뭐가 필요해요?', 'Opens a negotiation. It asks for conditions, not for a yes or no.', '협상을 여는 말입니다. 예, 아니오가 아니라 조건을 묻습니다.', 'meeting'),
  ('pr_d4_scope.doable', 'pr_d4_scope', 'Friday''s doable.', '금요일은 가능해요.', 'Doable = possible with effort.', 'doable은 노력하면 할 수 있다는 뜻입니다.', 'office'),
  ('pr_d4_scope.does_that_work', 'pr_d4_scope', 'Does that work for you?', '그렇게 하면 괜찮아요?', 'Checks agreement after a proposal. Never skip it.', '제안한 뒤 동의를 확인하는 말입니다. 빼먹지 마세요.', 'meeting'),
  ('pr_d4_scope.drop', 'pr_d4_scope', 'I have to drop the search filter ticket.', '검색 필터 티켓은 내려놓아야 해요.', '"Drop" = stop working on something to make room.', 'drop은 여유를 만들려고 하던 일을 내려놓는다는 뜻입니다.', 'office');

-- pr_d4_client: Setting expectations with the client
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d4_client', 1, 'greg',
   'The meeting room is empty. You dial Greg''s number on the speakerphone Tom tested on Monday.', '회의실이 비어 있습니다. 톰이 월요일에 점검해 둔 스피커폰으로 그렉의 번호를 누릅니다.',
   'Greg Whitfield.', 'Say who you are and where you are calling from, and ask if now is a good time.', '자신이 누구이고 어디 소속인지 밝히고, 지금 통화가 괜찮은지 물어보세요.',
   '[{"any":["good time","bad time","a minute","a few minutes","a moment"]}]',
   'Hi, Greg. It''s Priya Nair from Seaside Labs. Is now a good time?',
   '["Hi, Greg. It''s a medium latte with oat milk.","Hi, Greg. It''s the blue bin on the left.","Hi, Greg. It''s buy one, get one free."]',
   '["On the phone: your name, your company, then \\"Is now a good time?\\"","Key words: it''s Priya from Seaside Labs, is now a good time"]', '["전화에서는 이름, 회사, 그리고 \\"Is now a good time?\\" 순서입니다.","핵심 단어: it''s Priya from Seaside Labs, is now a good time"]',
   'greg', 'I''ve got five minutes. What''s the bottom line?', '5분 있습니다. 결론이 뭡니까?'),
  ('pr_d4_client', 2, 'greg',
   'Maya told you yesterday: lead with the bottom line.', '어제 마야가 말했습니다. 결론부터 말하라고.',
   'Go ahead.', 'Say you want to set expectations: the card refund fix ships Friday, but gift card refunds will slip to Wednesday.', '기대치를 맞추고 싶다고 하세요. 카드 환불 수정은 금요일에 나가지만 기프트 카드 환불은 수요일로 밀린다고요.',
   '[{"all":["expectations"]},{"all":["wednesday"]}]',
   'I want to set expectations. The card refund fix ships Friday, but gift card refunds will slip to Wednesday.',
   '["I want to make a reservation. A table for four on Friday, please.","I want to return this. The zipper broke on the first day.","I want to take Friday off. My friend is getting married."]',
   '["Start with \\"I want to set expectations\\", then the good news and the bad news.","Key words: set expectations, ships Friday, slip to Wednesday"]', '["\\"I want to set expectations\\"로 시작하고, 좋은 소식과 나쁜 소식을 말하세요.","핵심 단어: set expectations, ships Friday, slip to Wednesday"]',
   'greg', 'Slip? Why am I only hearing about this now?', '밀린다고요? 왜 이제야 그 얘기를 듣는 겁니까?'),
  ('pr_d4_client', 3, 'greg',
   'He does not sound happy. You stay calm.', '그렉의 목소리가 좋지 않습니다. 당신은 침착함을 잃지 않습니다.',
   'Well?', 'Say the team found the issue this morning and you wanted him to hear it from you right away.', '팀이 오늘 아침에 문제를 발견했고, 당신에게서 바로 직접 듣기를 바랐다고 하세요.',
   '[{"any":["this morning","right away","hear it from me","as soon as","first"]}]',
   'We found the issue this morning, and I wanted you to hear it from me right away.',
   '["We found your umbrella in the lobby, and Tom has it at the front desk.","We found a great taco place, and it has a patio.","We found a seat by the window, and the view is great."]',
   '["Say when you found out and why you are calling now.","Key words: found the issue this morning, hear it from me"]', '["언제 알게 됐는지, 왜 지금 전화하는지 말하세요.","핵심 단어: found the issue this morning, hear it from me"]',
   'greg', 'All right. I appreciate that. Does this affect Monday''s demo?', '알겠습니다. 그건 고맙군요. 월요일 데모에 영향이 있습니까?'),
  ('pr_d4_client', 4, 'greg',
   'This is the question that matters most to him.', '그렉에게 가장 중요한 질문입니다.',
   'I have my whole team coming on Monday.', 'Say no, the demo is not affected, because gift card refunds are not part of it.', '아니라고, 기프트 카드 환불은 데모에 들어 있지 않으니 데모에는 영향이 없다고 하세요.',
   '[{"any":["not affected","will not affect","does not affect","no impact","not part","on track"]}]',
   'No, the demo is not affected. Gift card refunds aren''t part of it.',
   '["No, the diner is not open. Breakfast starts at six thirty.","No, the bus is not late. It comes every fifteen minutes.","No, the milk is not on sale. It''s three twenty-nine."]',
   '["Answer the question first: no. Then one reason.","Key words: the demo is not affected, not part of it"]', '["질문에 먼저 답하세요. 아니요. 그다음 이유 하나.","핵심 단어: the demo is not affected, not part of it"]',
   'greg', 'Good. Can you guarantee Wednesday?', '좋습니다. 수요일은 확실히 보장할 수 있습니까?'),
  ('pr_d4_client', 5, 'greg',
   'A guarantee is a big word. Greg likes honest answers.', '보장은 무거운 말입니다. 그렉은 솔직한 답을 좋아합니다.',
   'I need something I can tell my boss.', 'Say you do not want to overpromise, but you are confident in Wednesday and will send him an update on Tuesday.', '지키지 못할 약속은 하고 싶지 않지만 수요일은 자신 있고, 화요일에 진행 상황을 보내겠다고 하세요.',
   '[{"any":["overpromise","over promise","confident","update"]}]',
   'I don''t want to overpromise. I''m confident in Wednesday, and I''ll send you an update on Tuesday.',
   '["I don''t want to be late. I''m taking the early bus, and I''ll bring an umbrella.","I don''t want dessert. I''m full, and I''ll take the check.","I don''t want a bag. I''m walking, and I''ll carry it."]',
   '["Be honest about the risk, then say when he will hear from you.","Key words: don''t want to overpromise, confident, send you an update"]', '["위험을 솔직히 말하고, 언제 다시 연락할지 알려 주세요.","핵심 단어: don''t want to overpromise, confident, send you an update"]',
   'greg', 'Fair enough. I like a straight answer. Talk to you Monday, Priya.', '좋습니다. 솔직한 답이 마음에 드네요. 월요일에 봅시다, 프리야.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d4_client.good_time', 'pr_d4_client', 'Is now a good time?', '지금 통화 괜찮으세요?', 'Polite on any phone call, and a must with a busy client.', '어떤 전화에서든 예의 바른 말이고, 바쁜 고객에게는 꼭 필요합니다.', 'office'),
  ('pr_d4_client.set_expectations', 'pr_d4_client', 'I want to set expectations.', '기대치를 맞춰 두고 싶습니다.', 'Tells people honestly what they will and will not get, before they are surprised.', '상대가 놀라기 전에 무엇을 받고 무엇을 못 받는지 솔직히 알려 주는 말입니다.', 'meeting'),
  ('pr_d4_client.slip', 'pr_d4_client', 'Gift card refunds will slip to Wednesday.', '기프트 카드 환불은 수요일로 밀립니다.', '"Slip" = be delayed. Softer than "We will be late."', 'slip은 늦어진다는 뜻입니다. "We will be late."보다 부드럽습니다.', 'office'),
  ('pr_d4_client.hear_it_from_me', 'pr_d4_client', 'I wanted you to hear it from me.', '제가 직접 말씀드리고 싶었습니다.', 'Bad news is best delivered early and in person.', '나쁜 소식은 일찍, 직접 전하는 것이 가장 좋습니다.', 'office'),
  ('pr_d4_client.not_affected', 'pr_d4_client', 'The demo is not affected.', '데모에는 영향이 없습니다.', 'Tells the client what stays the same. As important as what changes.', '고객에게 바뀌지 않는 것을 알려 줍니다. 바뀌는 것만큼 중요합니다.', 'meeting'),
  ('pr_d4_client.overpromise', 'pr_d4_client', 'I don''t want to overpromise.', '지키지 못할 약속은 하고 싶지 않습니다.', 'The rule is "underpromise and overdeliver".', '적게 약속하고 더 많이 해내라(underpromise and overdeliver)는 원칙이 있습니다.', 'office'),
  ('pr_d4_client.send_update', 'pr_d4_client', 'I''ll send you an update on Tuesday.', '화요일에 진행 상황을 보내 드리겠습니다.', 'Always end with the next time they will hear from you.', '언제 다시 연락할지 말하며 끝내세요.', 'office'),
  ('pr_d4_client.bottom_line', 'pr_d4_client', 'What''s the bottom line?', '결론이 뭡니까?', 'A busy person''s way of asking for the main point first.', '바쁜 사람이 핵심부터 말해 달라고 하는 말입니다.', 'meeting');

-- pr_d5_demo: Running the demo and the retro
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d5_demo', 1, 'derek',
   'Friday, eleven o''clock. The sun is out and the card fix shipped this morning.', '금요일 열한 시입니다. 해가 났고, 카드 환불 수정은 오늘 아침에 배포됐습니다.',
   'Everybody''s here, and the projector actually works today.', 'Open the demo and tell Jun he is up first: ask him to show the card payment fix.', '데모를 열고 준이 첫 순서라고 하세요. 카드 결제 수정을 보여 달라고 하세요.',
   '[{"any":["up first","go first","demo time","show us"]}]',
   'Okay, demo time! Jun, you''re up first. Want to show us the card payment fix?',
   '["Okay, lunch time! Jun, you''re buying. Want to try the taco place?","Okay, closing time! Jun, you''re the last one. Want to get the lights?","Okay, nap time!"]',
   '["\\"You''re up first\\" tells someone it is their turn to present.","Key words: demo time, you''re up first, show us"]', '["\\"You''re up first\\"는 발표할 첫 순서라는 말입니다.","핵심 단어: demo time, you''re up first, show us"]',
   'jun', 'Sure. Let me share my screen.', '네. 화면을 공유할게요.'),
  ('pr_d5_demo', 2, 'jun',
   'Jun''s screen appears on the wall.', '준의 화면이 벽에 뜹니다.',
   'Can everyone see it?', 'Say you can see it, and ask him to walk you through what changed.', '보인다고 하고, 무엇이 바뀌었는지 차례로 설명해 달라고 하세요.',
   '[{"any":["walk us through","walk me through","go ahead","we can see"]}]',
   'We can see it. Go ahead and walk us through what changed.',
   '["We can hear it. The music is coming from the park.","We can share it. The pizza is huge.","We can taste it. The soup is too salty."]',
   '["\\"Walk us through …\\" asks for a step-by-step explanation.","Key words: we can see it, walk us through"]', '["\\"Walk us through …\\"는 단계별로 설명해 달라는 말입니다.","핵심 단어: we can see it, walk us through"]',
   'jun', 'Now, if a payment fails, the user sees a clear error message, and we retry once automatically.', '이제 결제가 실패하면 사용자에게 분명한 오류 메시지가 보이고, 자동으로 한 번 다시 시도합니다.'),
  ('pr_d5_demo', 3, 'derek',
   'Everyone claps. Derek raises a finger. You look at the clock: ten minutes left.', '모두 박수를 칩니다. 데릭이 손가락을 듭니다. 시계를 보니 10분 남았습니다.',
   'That reminds me: we should rethink the whole retry library.', 'Ask to park that: you have ten minutes left and want to get to the retro.', '그 이야기는 잠시 미뤄 두자고 하세요. 10분 남았고 회고로 넘어가고 싶다고요.',
   '[{"any":["park","offline","circle back","parking lot"]}]',
   'Can we park that? We have ten minutes left, and I want to get to the retro.',
   '["Can we eat that? We have ten minutes left, and I''m starving.","Can we buy that? We have ten dollars left.","Can we walk there? We have ten blocks left."]',
   '["\\"Park\\" an idea = save it for later, like a car in a parking lot.","Key words: can we park that, ten minutes left"]', '["아이디어를 park한다는 것은 주차하듯 나중을 위해 세워 둔다는 뜻입니다.","핵심 단어: can we park that, ten minutes left"]',
   'derek', 'Parked. Put it on the list.', '미뤄 둘게요. 목록에 적어 두세요.'),
  ('pr_d5_demo', 4, 'derek',
   'You draw three columns on the whiteboard.', '화이트보드에 세 칸을 그립니다.',
   'Okay. Retro time.', 'Say you will start with what went well, and ask who wants to go first.', '잘된 점부터 시작하자고 하고, 누가 먼저 말할지 물어보세요.',
   '[{"all":["went well"]}]',
   'Let''s start with what went well. Who wants to go first?',
   '["Let''s start with the soup. Who wants crackers?","Let''s start with the top shelf. Who has the ladder?","Let''s start with your name. Who are you here to see?"]',
   '["A retro has three parts. Begin with the good one.","Key words: what went well, who wants to go first"]', '["회고는 세 부분입니다. 좋은 것부터 시작하세요.","핵심 단어: what went well, who wants to go first"]',
   'jun', 'The team was really supportive, and the code reviews were super helpful.', '팀이 정말 많이 도와줬고, 코드 리뷰가 큰 도움이 됐어요.'),
  ('pr_d5_demo', 5, 'jun',
   'Second column: what could be better. Jun takes a breath.', '둘째 칸은 더 나아질 점입니다. 준이 숨을 고릅니다.',
   'Some tickets could be clearer before planning. The refund bug was a little vague.', 'Say that is totally fair, and you will add acceptance criteria to every ticket from now on.', '정말 맞는 말이라고 하고, 앞으로 모든 티켓에 인수 조건을 넣겠다고 하세요.',
   '[{"any":["acceptance criteria","fair","criteria"]}]',
   'Totally fair. I''ll add acceptance criteria to every ticket from now on.',
   '["Totally full. I''ll take the rest home in a box.","Totally lost. I''ll ask the driver for directions.","Totally soaked. I''ll bring an umbrella from now on."]',
   '["The feedback is about your tickets. Take it well and promise a change.","Key words: totally fair, acceptance criteria, from now on"]', '["당신의 티켓에 대한 피드백입니다. 잘 받아들이고 바꾸겠다고 약속하세요.","핵심 단어: totally fair, acceptance criteria, from now on"]',
   'derek', 'I''ll second that. Clear tickets save everybody time.', '저도 동의해요. 티켓이 분명하면 모두의 시간이 절약되죠.'),
  ('pr_d5_demo', 6, 'derek',
   'Two minutes left. Third column: action items.', '2분 남았습니다. 셋째 칸은 액션 아이템입니다.',
   'Are we done? I can smell the weekend.', 'Say almost: recap the action items. You own the ticket template, and Derek adds tests for refunds.', '거의 다 됐다고 하고 액션 아이템을 정리하세요. 티켓 양식은 당신이, 환불 테스트 추가는 데릭이 맡습니다.',
   '[{"all":["action items"]},{"all":["recap"]}]',
   'Almost. Let''s recap the action items: I own the ticket template, and Derek adds tests for refunds.',
   '["Almost. Let''s split the check: I had the salad, and Derek had the burger.","Almost. Let''s grab the bags: I have the eggs, and Derek has the milk.","Almost. Let''s wait for the light."]',
   '["End with who does what: the \\"action items\\".","Key words: recap, action items, I own"]', '["누가 무엇을 하는지, 즉 action items로 마무리하세요.","핵심 단어: recap, action items, I own"]',
   'derek', 'On it. And we''re done two minutes early!', '맡을게요. 그리고 2분 일찍 끝났네요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d5_demo.up_first', 'pr_d5_demo', 'You''re up first.', '당신이 첫 순서예요.', '"You''re up" = it is your turn. Also "You''re up next."', '"You''re up"은 당신 차례라는 뜻입니다. "You''re up next."도 씁니다.', 'meeting'),
  ('pr_d5_demo.walk_us_through', 'pr_d5_demo', 'Walk us through what changed.', '무엇이 바뀌었는지 차례로 설명해 주세요.', 'Asks for a step-by-step explanation.', '단계별 설명을 부탁하는 말입니다.', 'meeting'),
  ('pr_d5_demo.park_that', 'pr_d5_demo', 'Can we park that?', '그건 잠시 미뤄 둘까요?', 'Saves an off-topic idea for later without killing it. The list is the "parking lot".', '주제에서 벗어난 아이디어를 버리지 않고 나중으로 미룹니다. 그 목록을 parking lot이라고 합니다.', 'meeting'),
  ('pr_d5_demo.went_well', 'pr_d5_demo', 'What went well?', '무엇이 잘됐나요?', 'The first retro question. The second is "What could be better?"', '회고의 첫 질문입니다. 둘째는 "What could be better?"입니다.', 'meeting'),
  ('pr_d5_demo.acceptance_criteria', 'pr_d5_demo', 'acceptance criteria', '인수 조건(완료 기준)', 'The list of things that must be true for a ticket to be done.', '티켓이 끝났다고 하려면 충족해야 하는 조건 목록입니다.', 'office'),
  ('pr_d5_demo.second_that', 'pr_d5_demo', 'I''ll second that.', '저도 동의해요.', 'Shows strong agreement with what someone just said.', '방금 나온 말에 힘주어 동의하는 표현입니다.', 'meeting'),
  ('pr_d5_demo.action_items', 'pr_d5_demo', 'Let''s recap the action items.', '액션 아이템을 정리합시다.', 'Action items = tasks from a meeting, each with an owner. "I own it" = it is my job.', 'action items는 회의에서 나온 할 일이고 저마다 담당자가 있습니다. "I own it"은 내 일이라는 뜻입니다.', 'meeting');

-- pr_d5_happy_hour: Happy hour at the Anchor
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_d5_happy_hour', 1, 'derek',
   'Friday afternoon. The sky is clear and half the office is already looking at the door.', '금요일 오후입니다. 하늘은 맑고, 사무실 사람 절반은 벌써 문 쪽을 보고 있습니다.',
   'Hey, a bunch of us are going to happy hour at the Anchor after work. You in?', 'Say you are in, but you need to send the client an update first.', '가겠다고 하되, 먼저 고객에게 진행 상황을 보내야 한다고 하세요.',
   '[{"any":["i am in","count me in","i will be there","love to"]}]',
   'I''m in! I just need to send the client an update first.',
   '["I''m out of milk! I just need to stop at the market first.","I''m lost! I just need to find the bus stop first.","I''m freezing! I just need to get my jacket first."]',
   '["Answer \\"You in?\\" with \\"I''m in!\\"","Key words: I''m in, send the client an update"]', '["\\"You in?\\"에는 \\"I''m in!\\"으로 답합니다.","핵심 단어: I''m in, send the client an update"]',
   'derek', 'Nice. We''re heading out at five thirty.', '좋아요. 우리는 다섯 시 반에 나가요.'),
  ('pr_d5_happy_hour', 2, 'derek',
   'The update to Greg will take a while.', '그렉에게 보낼 글은 시간이 좀 걸릴 것 같습니다.',
   'It''s perfect patio weather, so we''ll be outside.', 'Say you might be a few minutes late, and ask him to save you a seat.', '몇 분 늦을 수도 있다고 하고, 자리를 맡아 달라고 하세요.',
   '[{"any":["save me","few minutes late","running late","a little late","catch up"]}]',
   'I might be a few minutes late. Save me a seat?',
   '["I might be allergic to peanuts. Is there a nut-free menu?","I might need a bigger size. Is there a fitting room?","I might take the day off."]',
   '["\\"I might be …\\" is softer than \\"I will be …\\".","Key words: a few minutes late, save me a seat"]', '["\\"I might be …\\"는 \\"I will be …\\"보다 부드럽습니다.","핵심 단어: a few minutes late, save me a seat"]',
   'derek', 'You got it. Best seat on the patio.', '그럼요. 테라스에서 제일 좋은 자리로요.'),
  ('pr_d5_happy_hour', 3, 'derek',
   'Derek nods toward Jun''s empty chair.', '데릭이 준의 빈 의자 쪽으로 고개를 끄덕입니다.',
   'I asked Jun, too, but he''s wiped out. He took a rain check.', 'Say no wonder: he had a great first week.', '그럴 만하다고, 준이 첫 주를 정말 잘 보냈다고 하세요.',
   '[{"any":["no wonder","great first week","did great","great job","great week"]}]',
   'No wonder. He had a great first week.',
   '["No sugar. He has a medium latte.","No parking. He has to take the bus.","No receipt. He has to pay again."]',
   '["\\"No wonder\\" = that is not surprising.","Key words: no wonder, a great first week"]', '["\\"No wonder\\"는 놀랄 일이 아니라는 뜻입니다.","핵심 단어: no wonder, a great first week"]',
   'derek', 'He really did. Flagging that bug early saved us.', '정말 그래요. 그 버그를 일찍 알려 준 덕에 살았죠.'),
  ('pr_d5_happy_hour', 4, 'derek',
   'Derek gets a little serious for a moment.', '데릭이 잠깐 진지해집니다.',
   'By the way, thanks for handling the client yesterday. That could have gone badly.', 'Thank him, and say you could not have done it without him pairing with Jun.', '고맙다고 하고, 데릭이 준과 같이 작업해 주지 않았으면 못 했을 거라고 하세요.',
   '[{"any":["could not have","means a lot","team effort","without you"]}]',
   'Thanks, that means a lot. I couldn''t have done it without you pairing with Jun.',
   '["Thanks, that looks delicious. I''ll have the same.","Thanks, that fits perfectly. I''ll take two.","Thanks, that was my stop."]',
   '["Accept the compliment, then share the credit.","Key words: that means a lot, couldn''t have done it without you"]', '["칭찬을 받아들인 뒤 공을 나누세요.","핵심 단어: that means a lot, couldn''t have done it without you"]',
   'derek', 'Team effort. Okay, enough of that.', '다 같이 한 거죠. 자, 이런 얘기는 그만하고.'),
  ('pr_d5_happy_hour', 5, 'derek',
   'He grabs his jacket off the chair.', '데릭이 의자에 걸린 재킷을 집어 듭니다.',
   'First round''s on me.', 'Say no way: the first round is on you, because he earned it.', '안 된다고, 첫 잔은 당신이 사겠다고 하세요. 데릭은 그럴 자격이 있으니까요.',
   '[{"any":["on me","my treat","i am buying","i will get"]}]',
   'No way. The first round is on me. You earned it.',
   '["No way. The first bus is at six. You missed it.","No way. The first floor is closed. You need a badge.","No way. The first day is always hard."]',
   '["\\"It''s on me\\" = I will pay.","Key words: the first round is on me, you earned it"]', '["\\"It''s on me\\"는 내가 사겠다는 뜻입니다.","핵심 단어: the first round is on me, you earned it"]',
   'derek', 'I won''t argue with that. See you at the Anchor!', '그건 사양 안 할게요. 앵커에서 봐요!');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_d5_happy_hour.im_in', 'pr_d5_happy_hour', 'I''m in!', '저도 갈게요! / 낄게요!', 'Says yes to a plan. The opposite: "I''m out" or "I''ll pass."', '계획에 함께하겠다는 말입니다. 반대는 "I''m out"이나 "I''ll pass."입니다.', 'small-talk'),
  ('pr_d5_happy_hour.save_seat', 'pr_d5_happy_hour', 'Save me a seat?', '제 자리 좀 맡아 줄래요?', 'Short for "Can you save me a seat?"', '"Can you save me a seat?"을 줄인 말입니다.', 'small-talk'),
  ('pr_d5_happy_hour.wiped_out', 'pr_d5_happy_hour', 'He''s wiped out.', '그는 완전히 지쳤어요.', 'Very tired. Also "beat" or "exhausted".', '몹시 피곤하다는 뜻입니다. beat, exhausted도 씁니다.', 'small-talk'),
  ('pr_d5_happy_hour.no_wonder', 'pr_d5_happy_hour', 'No wonder.', '그럴 만하네요.', 'It is not surprising, given the reason.', '이유를 알고 보니 놀랍지 않다는 뜻입니다.', 'small-talk'),
  ('pr_d5_happy_hour.means_a_lot', 'pr_d5_happy_hour', 'Thanks, that means a lot.', '고마워요, 큰 힘이 돼요.', 'A warm way to accept a compliment.', '칭찬을 따뜻하게 받아들이는 말입니다.', 'small-talk'),
  ('pr_d5_happy_hour.couldnt_have', 'pr_d5_happy_hour', 'I couldn''t have done it without you.', '당신 없이는 못 했을 거예요.', 'Shares the credit. Good leaders say it often.', '공을 나누는 말입니다. 좋은 리더는 자주 씁니다.', 'office'),
  ('pr_d5_happy_hour.on_me', 'pr_d5_happy_hour', 'The first round is on me.', '첫 잔은 제가 살게요.', '"A round" is one drink for everyone in the group. "On me" = I pay.', 'a round는 일행 모두에게 돌아가는 한 잔입니다. on me는 내가 낸다는 뜻입니다.', 'small-talk');

-- pr_w_brunch: Weekend brunch at the diner
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_brunch', 1, 'rosa',
   'A sunny weekend morning. The diner smells like coffee and bacon.', '화창한 주말 아침입니다. 다이너에 커피와 베이컨 냄새가 가득합니다.',
   'Morning, hon! Just you today?', 'Say it is just you, and ask for a table by the window.', '혼자라고 하고, 창가 자리를 부탁하세요.',
   '[{"any":["window","just me","table for one"]}]',
   'Just me today. Could I get a table by the window?',
   '["Just milk today. Could I get a paper bag?","Just a trim today. Could I get it a little shorter?","Just looking today."]',
   '["Answer her question, then ask for the seat you want.","Key words: just me, a table by the window"]', '["질문에 답한 뒤 원하는 자리를 부탁하세요.","핵심 단어: just me, a table by the window"]',
   'rosa', 'Sure thing. Right this way.', '그럼요. 이쪽으로 와요.'),
  ('pr_w_brunch', 2, 'rosa',
   'Rosa comes over with a pot of coffee.', '로사가 커피 주전자를 들고 옵니다.',
   'Coffee to start?', 'Say yes, and ask what the brunch specials are today.', '네라고 하고, 오늘 브런치 스페셜이 무엇인지 물어보세요.',
   '[{"any":["specials","special"]}]',
   'Yes, please. What are the brunch specials today?',
   '["Yes, please. What are the story points today?","Yes, please. What are the visiting hours today?","Yes, please. What are the bus fares today?"]',
   '["\\"Specials\\" are dishes only on today''s menu.","Key words: yes please, brunch specials"]', '["specials는 오늘만 파는 메뉴입니다.","핵심 단어: yes please, brunch specials"]',
   'rosa', 'We''ve got a veggie omelet with home fries and toast, or blueberry pancakes.', '채소 오믈렛에 홈 프라이와 토스트가 나오는 것, 아니면 블루베리 팬케이크가 있어요.'),
  ('pr_w_brunch', 3, 'rosa',
   'She takes a pencil from behind her ear.', '로사가 귀 뒤에 꽂아 둔 연필을 뺍니다.',
   'What''ll it be, hon?', 'Order the veggie omelet, and ask for wheat toast instead of white.', '채소 오믈렛을 주문하고, 흰 빵 대신 통밀 토스트로 해 달라고 하세요.',
   '[{"all":["omelet"]},{"all":["omelette"]}]',
   'I''ll have the veggie omelet. Can I get wheat toast instead of white?',
   '["I''ll have the refund bug. Can I get more details first?","I''ll have the small room. Can I get it until four?","I''ll have the large latte. Can I get it iced?"]',
   '["\\"I''ll have …\\" orders. \\"… instead of …\\" changes one thing.","Key words: I''ll have the veggie omelet, wheat toast instead of white"]', '["\\"I''ll have …\\"로 주문하고 \\"… instead of …\\"로 하나를 바꿉니다.","핵심 단어: I''ll have the veggie omelet, wheat toast instead of white"]',
   'rosa', 'Wheat toast, you got it. It''ll be right out.', '통밀 토스트, 알겠어요. 금방 나와요.'),
  ('pr_w_brunch', 4, 'rosa',
   'The plate is empty. Rosa stops by with the coffee pot again.', '접시가 비었습니다. 로사가 다시 커피 주전자를 들고 들릅니다.',
   'How was everything?', 'Say it was delicious as always, and ask for the check.', '언제나처럼 맛있었다고 하고, 계산서를 부탁하세요.',
   '[{"any":["check","bill"]}]',
   'Delicious, as always. Could I get the check, please?',
   '["Delicious, as always. Could I get the recipe, please?","Busy, as always. Could I get a day off, please?","Late, as always. Could I get a ride, please?"]',
   '["A compliment first, then \\"Could I get the check?\\"","Key words: delicious, as always, the check"]', '["먼저 칭찬하고, \\"Could I get the check?\\"이라고 하세요.","핵심 단어: delicious, as always, the check"]',
   'rosa', 'Here you go, hon. Eighteen forty with tax. No rush.', '여기요. 세금 포함해서 18달러 40센트예요. 천천히 해요.'),
  ('pr_w_brunch', 5, 'rosa',
   'The check says $17.00 plus $1.40 tax. Twenty percent of seventeen dollars is $3.40.', '계산서에는 17달러에 세금 1달러 40센트라고 적혀 있습니다. 17달러의 20퍼센트는 3달러 40센트입니다.',
   'Cash or card?', 'Say you will put it on your card, and ask her to add a twenty percent tip.', '카드로 하겠다고 하고, 팁 20퍼센트를 더해 달라고 하세요.',
   '[{"all":["tip"]},{"any":["twenty percent","20 percent","gratuity"]}]',
   'I''ll put it on my card. And please add a twenty percent tip.',
   '["I''ll put it on my calendar. And please send me the agenda.","I''ll put it in the fridge. And please close the door.","I''ll put it in the blue bin."]',
   '["Tip 15 to 20 percent of the price before tax.","Key words: put it on my card, twenty percent tip"]', '["팁은 세전 가격의 15~20퍼센트입니다.","핵심 단어: put it on my card, twenty percent tip"]',
   'rosa', 'Aw, thank you, hon! You have a great weekend.', '어머, 고마워요! 주말 잘 보내요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_w_brunch.just_me', 'pr_w_brunch', 'Just me today.', '오늘은 혼자예요.', 'The answer to "How many?" or "Just you?" at a restaurant.', '식당에서 "How many?"나 "Just you?"라고 물을 때 하는 답입니다.', 'food'),
  ('pr_w_brunch.specials', 'pr_w_brunch', 'What are the specials today?', '오늘의 스페셜은 뭐예요?', 'Specials are not on the regular menu, so you have to ask.', '스페셜은 기본 메뉴판에 없어서 물어봐야 합니다.', 'food'),
  ('pr_w_brunch.instead_of', 'pr_w_brunch', 'Can I get wheat toast instead of white?', '흰 빵 대신 통밀 토스트로 주시겠어요?', 'American diners are happy to change a dish. Just ask.', '미국 다이너는 메뉴를 바꿔 달라는 부탁을 잘 들어줍니다. 그냥 물어보세요.', 'food'),
  ('pr_w_brunch.as_always', 'pr_w_brunch', 'Delicious, as always.', '언제나처럼 맛있었어요.', 'A compliment from a regular.', '단골이 하는 칭찬입니다.', 'food'),
  ('pr_w_brunch.put_on_card', 'pr_w_brunch', 'I''ll put it on my card.', '카드로 할게요.', '"Put it on" = charge it to.', 'put it on은 그쪽으로 결제한다는 뜻입니다.', 'food'),
  ('pr_w_brunch.tip', 'pr_w_brunch', 'Please add a twenty percent tip.', '팁 20퍼센트를 더해 주세요.', 'At a table, 15 to 20 percent of the price before tax. Servers depend on tips.', '테이블에서 먹으면 세전 가격의 15~20퍼센트입니다. 종업원의 수입은 팁에 달려 있습니다.', 'food');

-- pr_w_farmers: The farmers market in Seaside Park
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_farmers', 1, 'carl',
   'Seaside Park on a sunny morning. Carl is on his usual bench with a paper bag full of peaches.', '화창한 아침의 시사이드 공원입니다. 칼이 늘 앉는 벤치에 복숭아가 가득 든 종이봉투를 들고 있습니다.',
   'Well, look who it is! Morning, Priya. Beautiful day, huh?', 'Agree that it is gorgeous, and ask if he is here for the farmers market too.', '정말 좋은 날이라고 맞장구치고, 칼도 파머스 마켓에 왔는지 물어보세요.',
   '[{"any":["farmers market","market"]}]',
   'Gorgeous! Are you here for the farmers market too?',
   '["Gorgeous! Are you here for the sprint demo too?","Gorgeous! Are you here for your badge too?","Gorgeous! Are you here for the dentist too?"]',
   '["Agree about the weather, then ask why he is here.","Key words: gorgeous, farmers market"]', '["날씨에 맞장구친 뒤 여기 온 이유를 물어보세요.","핵심 단어: gorgeous, farmers market"]',
   'carl', 'Already been. Got the peaches from the stand by the fountain. Best in town.', '벌써 다녀왔지. 분수대 옆 가판에서 복숭아를 샀어. 이 동네 최고야.'),
  ('pr_w_farmers', 2, 'carl',
   'He holds up a peach the size of a baseball.', '칼이 야구공만 한 복숭아를 들어 보입니다.',
   'Look at that. You don''t get these at the store.', 'Say they look amazing and ask how much they are.', '정말 맛있어 보인다고 하고, 얼마인지 물어보세요.',
   '[{"any":["how much","price","cost"]}]',
   'They look amazing. How much are they?',
   '["They look tired. How long was the flight?","They look busy. How late are they open?","They look lost. Where are they going?"]',
   '["Ask the price with \\"How much …?\\"","Key words: look amazing, how much"]', '["\\"How much …?\\"로 값을 물어보세요.","핵심 단어: look amazing, how much"]',
   'carl', 'Four dollars a pound, or three pounds for ten. Tell them Carl sent you.', '1파운드에 4달러, 3파운드에 10달러야. 칼이 보냈다고 해.'),
  ('pr_w_farmers', 3, 'carl',
   'He points across the grass at the white tents.', '칼이 잔디밭 건너 하얀 천막들을 가리킵니다.',
   'Bring cash, though. Some of the stands don''t take cards.', 'Say that is good to know, and ask if there is an ATM nearby.', '알려 줘서 다행이라고 하고, 근처에 현금 인출기가 있는지 물어보세요.',
   '[{"all":["atm"]},{"any":["cash machine","get cash"]}]',
   'Good to know. Is there an ATM nearby?',
   '["Good to know. Is there a projector in the room?","Good to know. Is there a vegetarian option?","Good to know. Is there a later flight?"]',
   '["A machine that gives you cash is an ATM.","Key words: good to know, ATM nearby"]', '["현금을 뽑는 기계는 ATM입니다.","핵심 단어: good to know, ATM nearby"]',
   'carl', 'There''s one by the park entrance, right next to the coffee cart.', '공원 입구에 하나 있어. 커피 카트 바로 옆이야.'),
  ('pr_w_farmers', 4, 'carl',
   'Carl moves over to make room on the bench.', '칼이 벤치 옆자리를 내줍니다.',
   'So how''s work? Still running all those meetings?', 'Say always: it was a hectic week, but the team shipped on time.', '늘 그렇다고, 정신없는 한 주였지만 팀이 제때 배포했다고 하세요.',
   '[{"any":["hectic","busy","shipped","on time","crazy"]}]',
   'Always. It was a hectic week, but we shipped on time.',
   '["Always. It was a window seat, but I slept the whole way.","Always. It was a large pizza, but I ate it all.","Never. It was a long line, so I went home."]',
   '["One word for the week, then the good result.","Key words: hectic week, shipped on time"]', '["한 주를 한 단어로 말하고, 좋은 결과를 덧붙이세요.","핵심 단어: hectic week, shipped on time"]',
   'carl', 'That''s what I like to hear. But you work too hard, you know.', '듣기 좋은 소식이네. 그런데 자네는 일을 너무 많이 해.'),
  ('pr_w_farmers', 5, 'carl',
   'Music drifts over from the market.', '마켓 쪽에서 음악 소리가 들려옵니다.',
   'What are you doing this weekend to relax?', 'Say you are going to cook with whatever looks fresh, and then take it easy.', '싱싱해 보이는 걸로 요리하고, 그다음에는 푹 쉴 거라고 하세요.',
   '[{"any":["cook","take it easy","relax","fresh"]}]',
   'I''m going to cook with whatever looks fresh, and then take it easy.',
   '["I''m going to call the client, and then write the roadmap.","I''m going to file my expenses, and then book a flight.","I''m going to reset my password."]',
   '["\\"I''m going to …\\" for plans. \\"Take it easy\\" = rest.","Key words: cook, whatever looks fresh, take it easy"]', '["계획은 \\"I''m going to …\\"로 말합니다. take it easy는 쉰다는 뜻입니다.","핵심 단어: cook, whatever looks fresh, take it easy"]',
   'carl', 'That''s the spirit. Here, take a peach for the road.', '바로 그거야. 자, 가는 길에 복숭아 하나 먹어.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_w_farmers.look_who', 'pr_w_farmers', 'Well, look who it is!', '아니, 이게 누구야!', 'A warm greeting when you run into someone you know.', '아는 사람을 우연히 만났을 때 하는 반가운 인사입니다.', 'small-talk'),
  ('pr_w_farmers.how_much', 'pr_w_farmers', 'How much are they?', '얼마예요?', 'Use "are they" for more than one thing, "is it" for one.', '여러 개면 are they, 하나면 is it을 씁니다.', 'shopping'),
  ('pr_w_farmers.a_pound', 'pr_w_farmers', 'four dollars a pound', '1파운드에 4달러', 'Produce is sold by the pound (lb). One pound is about 450 grams.', '과일과 채소는 파운드(lb) 단위로 팝니다. 1파운드는 약 450그램입니다.', 'shopping'),
  ('pr_w_farmers.good_to_know', 'pr_w_farmers', 'Good to know.', '알아 두면 좋겠네요.', 'Thanks someone for a useful piece of information.', '쓸모 있는 정보를 알려 줘서 고맙다는 말입니다.', 'small-talk'),
  ('pr_w_farmers.atm', 'pr_w_farmers', 'Is there an ATM nearby?', '근처에 현금 인출기가 있나요?', 'Small stands and markets often take cash only.', '작은 가판이나 시장은 현금만 받는 곳이 많습니다.', 'shopping'),
  ('pr_w_farmers.hectic', 'pr_w_farmers', 'It was a hectic week.', '정신없는 한 주였어요.', 'Hectic = very busy, with a lot going on at once.', 'hectic은 여러 일이 한꺼번에 몰려 몹시 바쁘다는 뜻입니다.', 'small-talk'),
  ('pr_w_farmers.take_it_easy', 'pr_w_farmers', 'I''m going to take it easy.', '푹 쉴 거예요.', 'To relax and not do much. Also a casual goodbye: "Take it easy!"', '별일 없이 쉰다는 뜻입니다. "Take it easy!"는 편한 작별 인사로도 씁니다.', 'small-talk');

-- pr_w_grocery: Groceries for the week
REPLACE INTO turns (episode, seq, speaker, situation, situation_ko, line, prompt, prompt_ko, answers, model, distractors, hints, hints_ko, reply_speaker, reply_line, reply_ko) VALUES
  ('pr_w_grocery', 1, 'mike',
   'Fairview Market. Your cart is full for the week: vegetables, eggs, cheese, coffee beans.', '페어뷰 마켓입니다. 채소, 달걀, 치즈, 커피 원두까지 한 주 먹을 것으로 카트가 가득합니다.',
   'Hi there! Did you find everything okay?', 'Say you did, and that you brought your own bags.', '다 찾았다고 하고, 장바구니를 가져왔다고 하세요.',
   '[{"any":["own bags","my bags","reusable","own bag"]}]',
   'I did, thanks. Oh, and I brought my own bags.',
   '["I did, thanks. Oh, and I booked the large room.","I did, thanks. Oh, and I sent the invite.","I did, thanks. Oh, and I parked on the street."]',
   '["Answer yes, then tell him about your bags.","Key words: I did, brought my own bags"]', '["네라고 답한 뒤 장바구니 이야기를 하세요.","핵심 단어: I did, brought my own bags"]',
   'mike', 'Nice! That''s five cents off for each bag.', '좋네요! 봉투 하나에 5센트씩 빼 드려요.'),
  ('pr_w_grocery', 2, 'mike',
   'You watch the prices on the screen. The cheddar comes up as $4.49, but the sign on the shelf said $3.49.', '화면에 찍히는 값을 봅니다. 체다 치즈가 4달러 49센트로 찍혔는데, 진열대 표지에는 3달러 49센트라고 돼 있었습니다.',
   'Did you know the ice cream is two for eight this week?', 'Politely say you think the cheese rang up wrong: the sign said it was on sale.', '정중하게 치즈 값이 잘못 찍힌 것 같다고 하세요. 표지에는 할인이라고 돼 있었다고요.',
   '[{"any":["rang up","wrong price","on sale","sign said","overcharged"]}]',
   'Sorry, I think the cheese rang up wrong. The sign said it was on sale.',
   '["Sorry, I think the meeting ran long. The invite said thirty minutes.","Sorry, I think the bus left early. The schedule said nine.","Sorry, I think I left my badge at home."]',
   '["\\"Ring up\\" = enter the price at the register. Past: rang up.","Key words: I think, rang up wrong, on sale"]', '["ring up은 계산대에서 값을 찍는다는 뜻입니다. 과거형은 rang up.","핵심 단어: I think, rang up wrong, on sale"]',
   'mike', 'Let me check. You''re right, it''s three forty-nine. I''ll fix that.', '확인해 볼게요. 맞네요, 3달러 49센트예요. 고쳐 드릴게요.'),
  ('pr_w_grocery', 3, 'mike',
   'You take a coupon out of your wallet.', '지갑에서 쿠폰을 꺼냅니다.',
   'Anything else before I total it up?', 'Ask if you can use this coupon: it is for the coffee beans.', '이 쿠폰을 쓸 수 있는지 물어보세요. 커피 원두용 쿠폰입니다.',
   '[{"all":["coupon"]}]',
   'Can I use this coupon? It''s for the coffee beans.',
   '["Can I use this room? It''s for the client call.","Can I use this desk? It''s for the new developer.","Can I use your umbrella? It''s raining."]',
   '["Hand it over and ask \\"Can I use …?\\"","Key words: use this coupon, coffee beans"]', '["쿠폰을 내밀며 \\"Can I use …?\\"로 물어보세요.","핵심 단어: use this coupon, coffee beans"]',
   'mike', 'Sure. It expires tomorrow, so you''re just in time. Two dollars off.', '그럼요. 내일까지라서 딱 맞춰 오셨네요. 2달러 할인입니다.'),
  ('pr_w_grocery', 4, 'mike',
   'The total appears on the card reader.', '카드 단말기에 합계가 뜹니다.',
   'Debit or credit?', 'Say credit, and ask for the receipt in the bag.', '신용카드라고 하고, 영수증은 봉투에 넣어 달라고 하세요.',
   '[{"all":["credit"]}]',
   'Credit, please. And could you put the receipt in the bag?',
   '["Oat milk, please. And could you make it extra hot?","Wednesday, please. And could you book the large room?","Medium rare, please. And could you bring some ketchup?"]',
   '["Choose one of the two, then say where the receipt goes.","Key words: credit, receipt in the bag"]', '["둘 중 하나를 고르고, 영수증을 어디에 둘지 말하세요.","핵심 단어: credit, receipt in the bag"]',
   'mike', 'You got it. You''re all set.', '알겠어요. 다 됐습니다.'),
  ('pr_w_grocery', 5, 'mike',
   'Two full bags. They are heavier than they look.', '가득 찬 봉투가 둘입니다. 보기보다 무겁습니다.',
   'Need a hand out to your car?', 'Say no, thanks: you have got it, and you live just around the corner.', '괜찮다고 하세요. 혼자 들 수 있고, 바로 근처에 산다고요.',
   '[{"any":["got it","i am good","around the corner","manage"]},{"all":["no"],"any":["thanks","thank"]}]',
   'No, thanks. I''ve got it. I live just around the corner.',
   '["Yes, please. I have three more carts outside.","Sure. I''ll take the large latte with oat milk.","Maybe later. I have a meeting at two."]',
   '["A polite no, then \\"I''ve got it.\\"","Key words: no thanks, I''ve got it, around the corner"]', '["정중히 거절하고 \\"I''ve got it.\\"이라고 하세요.","핵심 단어: no thanks, I''ve got it, around the corner"]',
   'mike', 'Have a good one! Enjoy the rest of your weekend.', '좋은 하루 보내세요! 남은 주말 잘 보내시고요.');

REPLACE INTO phrases (id, episode, text, meaning_ko, note, note_ko, category) VALUES
  ('pr_w_grocery.find_everything', 'pr_w_grocery', 'Did you find everything okay?', '찾으시는 건 다 찾으셨어요?', 'What cashiers ask at checkout. "I did, thanks" is enough.', '계산원이 계산대에서 묻는 말입니다. "I did, thanks"면 충분합니다.', 'shopping'),
  ('pr_w_grocery.own_bags', 'pr_w_grocery', 'I brought my own bags.', '장바구니를 가져왔어요.', 'Many stores charge for bags or give a small discount for yours.', '봉투값을 받거나, 장바구니를 가져오면 조금 깎아 주는 가게가 많습니다.', 'shopping'),
  ('pr_w_grocery.rang_up_wrong', 'pr_w_grocery', 'I think the cheese rang up wrong.', '치즈 값이 잘못 찍힌 것 같아요.', '"I think" keeps it polite. Mistakes at the register are common.', 'I think를 붙이면 공손해집니다. 계산대에서의 실수는 흔합니다.', 'shopping'),
  ('pr_w_grocery.on_sale', 'pr_w_grocery', 'The sign said it was on sale.', '표지에는 할인이라고 돼 있었어요.', '"On sale" = at a lower price. "For sale" = you can buy it.', 'on sale은 할인 중, for sale은 판매 중이라는 뜻입니다.', 'shopping'),
  ('pr_w_grocery.coupon', 'pr_w_grocery', 'Can I use this coupon?', '이 쿠폰 쓸 수 있어요?', 'Coupons have an expiration date. Check it first.', '쿠폰에는 유효 기간이 있습니다. 먼저 확인하세요.', 'shopping'),
  ('pr_w_grocery.debit_or_credit', 'pr_w_grocery', 'Debit or credit?', '체크카드예요, 신용카드예요?', 'Debit takes the money from your bank account right away.', 'debit은 은행 계좌에서 바로 돈이 빠져나갑니다.', 'shopping'),
